// v2 glossary (V2-SPEC §6.7). Owner: WS6. Starts from the v1 glossary, overrides every entry that carried a canon date
// or scenario reference (canon appears only on the end screen), and adds the v2 terms. Bodies link with [[id]].
import { GLOSSARY, type Term } from '../glossary';

const V2: Record<string, Term> = {
  // ── overrides of v1 entries (no canon dates) ──
  rdmult: { title: 'Research speed', body: 'How fast your lab turns compute and people into results, as × the leading lab in Jul 2025. Your AI staff\'s part (their [[effectiveLabour|work in experiments]], [[researchTaste|research taste]] and adopted research-speed ideas) shows in the breakdown as "× from AI staff"; it stays near ×1 until their [[coverage|share they can do alone]] rises.', src: 'research/13 §2.8; MODEL-V3 §6' },
  sc: { title: 'Superhuman Coder', body: 'A model whose software-engineering [[fit|skill]] reaches the [[bestHuman|best human in the world]], that can do at least 90% of the work alone, with an AI work-hour cheaper than your best engineers\'. As AI 2027 defines it. 10 levels on the skill ruler (10 = best human).', src: 'MODEL-V3 §6.4; research/13 §2.8' },
  sar: { title: 'Superhuman AI Researcher', body: 'The superhuman-coder test passed for experiments and for research ideas and taste: skill at the [[bestHuman|best human]], at least 90% of the work done alone. 12 levels on the skill ruler.', src: 'MODEL-V3 §6.4; research/13 §2.8' },
  siar: { title: 'Superintelligent AI Researcher', body: 'Research-ideas [[fit|skill]] beyond the best human by twice the gap between the median expert and the best human. 13.5 levels on the skill ruler.', src: 'MODEL-V3 §6.4; research/13 §2.4' },
  asi: { title: 'Superintelligence', body: 'Every cognitive [[workType|work type]] beyond its best human by twice the gap between the median expert and the best human (15 levels). The game resolves here: the outcome depends on the hidden [[misalign|misalignment]] of whoever gets there first and on who holds [[leverage]].', src: 'MODEL-V3 §6.4; V2-SPEC §5.2' },
  approval: { title: 'Net approval', body: 'Approve minus disapprove for your company (−100..+100). Moves with incidents, jobs, releases and disclosure.', src: 'research/07 §1.2' },
  salience: { title: 'Salience', body: 'Share of the public naming AI as the most important problem.', src: 'research/07 §1.2' },
  oversight: { title: 'Oversight committee', body: 'A joint company-government body that votes on key decisions. Can form late in the game when government [[securityDemand|security demand]] peaks.', src: 'research/07 §1.1' },
  cdz: { title: 'Centralized development zone', body: 'A state-run site where China pools its national compute under one lab.', src: 'research/10' },
  wsl: { title: 'Weight security level', body: 'WSL 1–5 (RAND). WSL n holds against an OC n attacker with high odds over two months. Raising it costs money and slows research ([[siloing]]).', src: 'RAND SL framework; research/17' },
  neuralese: { title: 'Neuralese', body: 'Latent reasoning and memory that is not readable text. Faster and cheaper to serve, but reasoning monitors go blind: [[monitorability]] drops to almost nothing. Needs the latent-reasoning discovery and a latent base model [[shape|architecture]].', src: 'V2-SPEC §3.3.2, §3.5.1' },
  // ── v2 terms ──
  L: { title: 'Capability', body: 'How capable your best internal model is as MEASURED by your evals: its [[domains|skill]] per domain, read off the last eval\'s benchmark scores, then averaged over the cognitive domains, in levels (10 = best human). Eval noise, weaker or stronger elicitation and [[sand|sandbagging]] all move it. Milestones: [[reliableAgent]] 6.5, [[researchAgent]] 8.5, [[sc]] 10, [[sar]] 12, [[siar]] 13.5, [[asi]] 15.', src: 'V2-SPEC §3.1.5' },
  sightLimit: { title: 'Sight limit', body: 'The most capable model your [[detector|instruments]] can still read for hidden goals (scheming, faking alignment, sandbagging, power seeking) at 50% or better, on what you believe. A tick on the capability ruler: "1.2 levels short of" your best model. Each instrument loses [[halfStrength|reliability]] the further a model is beyond the one it was validated on. A model past your sight limit can hide what it wants.', src: 'SAFETY-REDESIGN §2.2 (5); SR-11' },
  prodfn: { title: 'Gets', body: 'What a project works with: its experiment compute and research engineers (each worth less without the other), and its scientists\' work × their [[researchTaste|taste]]. Lab [[labSpeed|research speed]] is the sum over projects.', src: 'research/13 §1.3; MODEL-V3 §5.3' },
  bottleneck: { title: 'Limited by', body: 'The input that would speed research up most: [[computeBound|compute]] (experiment compute), [[laborBound|research engineers]] (people and AI staff), [[humanBound|scientists]], or [[tasteBound|idea quality]] (late: which ideas to try).', src: 'research/13 §1.6' },
  runway: { title: 'Runway', body: 'Quarters until projected [[liquidity]] falls below minimum operating cash (one month of running costs), from a cash forecast over the next 8 quarters: revenue at today\'s run rate, running costs, and each payment in the quarter it falls due ([[ledger]] contracts, chip balances on delivery, site [[capex]] on its build schedule, unconditional tranches when they land). "8q+" means it lasts the whole forecast. [[healthy|Healthy]] ≥ 6q, [[tight|Tight]] 3–6q, [[distress|Distress]] < 3q.', src: 'research/15 §1.8' },
  parentBudget: { title: 'Parent budget', body: 'A big-tech division has no equity and no valuation: its parent sets a yearly budget (Jul–Jun) at each [[parentReview|review]] and pays it at the start of each quarter. The budget = the parent\x27s plan (its capex path: $16B in the first year, ×1.75 a year for three years, then ×1.3) × a factor read off [[parentConf|parent confidence]]: the full plan at 60 or above, falling to half at 0. Your product revenue goes to the parent. Unspent budget stays as cash; spending more is over budget: the parent pays the bills (a division cannot go broke) and its later payments repay it first. No equity raises, deals or debt.', src: 'FINANCE-V3 §13; research/18 §3.2' },
  parentConf: { title: 'Parent confidence', body: 'How much the parent trusts its division, 0–100 (the division\x27s board confidence; it drifts toward 60 a tenth of the gap each quarter). It moves on [[parentGoal|parent goals]] (met +10 each, missed by more than 20% of the gain −10 each, at a third of the year each), on overspend at each review (−30 × overspend ÷ the year\x27s budget, at most −30, while the parent is still covering it) and on public incidents (×0.5). At the review it sets the next budget: plan × min(100%, 50% + confidence ÷ 120). A division head is never voted out: low confidence costs budget, not the game.', src: 'FINANCE-V3 §13' },
  parentGoal: { title: 'Parent goal', body: 'At each [[parentReview|review]] the parent sets the year\x27s goals on your own trend, as a raise\x27s base pitch: a public model level (capability), owned and firm compute online (scale) and a revenue run-rate (adoption; none while there is no revenue). Judged at the next review like a [[promise]]: met moves [[parentConf|parent confidence]] +30 × its weight (a third), missed by more than 20% of the gain −30 × its weight, in between nothing. Never cash.', src: 'FINANCE-V3 §13, §2.2–2.4' },
  parentReview: { title: 'Parent review', body: 'Once a year, on 1 July: the parent judges the year\x27s [[parentGoal|goals]], minds any overspend it is still covering, sets the new [[parentBudget|budget]] from [[parentConf|parent confidence]] and sets the new goals.', src: 'FINANCE-V3 §13' },
  startType: { title: 'Start type', body: 'Where your company begins: a frontier leader, a challenger lab, a big-tech AI division or a well-funded spinout. The rules are the same for all; only the start state differs. Difficulty is a label; scoring is the same.', src: 'STRUCTURE §4.8; research/18' },
  raiseCeiling: { title: 'Raise ceiling', body: 'The most you can raise this quarter: the smaller of your share of the [[investorPool|investor pool]] and the [[dilutionCap|dilution cap]] at the round\'s price (your [[pitch]] moves the price). Asking above it lowers the odds the round closes.', src: 'FINANCE-V3 §2.1' },
  scrutiny: { title: 'Scrutiny', body: 'How closely press, regulators and watchdogs watch you (0–100). High scrutiny speeds discovery of cover-ups and raises the odds of rules.', src: 'research/17 §1.1' },
  credibility: { title: 'Credibility', body: 'Whether outsiders believe your claims (0–100). Kept commitments raise it; broken ones and discovered cover-ups cost ×3.', src: 'research/17 §1.1' },
  trust: { title: 'Trust', body: 'Per-[[counterparty]] relationship stock (0–100). Trust unlocks [[access]] rungs and makes favors cheaper.', src: 'research/17 §1.1' },
  access: { title: 'Access rung', body: 'How deep a counterparty is involved: 0 none, 1 briefings, 2 early access, 3 pre-deployment testing, 4 embedded. Rungs need trust thresholds 25/45/65/80.', src: 'research/17 §1.1' },
  favors: { title: 'Favors', body: 'Tokens owed to you (max 5, they expire). Spent to soften rules or to unlock agreements.', src: 'research/17 §1.1' },
  commitment: { title: 'Commitment', body: 'A public promise with a condition (e.g. no BIO ≥ 10 deployment without classifiers). Keeping it builds [[credibility]]; breaking it costs the listed trust and credibility.', src: 'research/17 §1.2' },
  lead: { title: 'Lead days', body: 'Estimated days your best INTERNAL model is ahead of a rival or China (negative = behind). Built from public releases and evaluator reports; ± is the [[intelError|intel uncertainty]].', src: 'V2-SPEC §3.10.3' },
  leverage: { title: 'Leverage', body: 'The share of economic, governmental, military and infrastructure decisions routed through a lab\'s models (control index). Thresholds: [[entrenched]] 15%, [[indispensable]] 35%, [[decisive]] 60%.', src: 'research/16 §2' },
  agenda: { title: 'Programme', body: 'A safety [[researchLine|programme]] (interpretability, control, evals, …): ongoing research whose real promise in this world is hidden. You see its [[lineHealth|outlook]], which firms up as [[finding|results]] arrive.', src: 'research/14 §1.2' },
  finding: { title: 'Result', body: 'What a finished idea or project gave you: a new [[detector|instrument]], a [[safetyMethod|method]], an eval, a [[umode|new failure mode]] discovered, a dead end, a weaker version of something known, help for capabilities, or a false lead that hides a trait rather than reading it.', src: 'research/14 §1.3' },
  technique: { title: 'Instrument', body: 'An owned way of reading a model\'s traits, from safety research. Its [[halfStrength|reliability]] falls as models grow past the one it was validated on; training against it teaches the model to hide from it ([[goodhart|trained against]]).', src: 'research/14 §1.4' },
  umode: { title: 'New failure mode', body: 'A way models can fail that you do not yet know about. Incidents it causes show as "unexplained" until a programme discovers it.', src: 'research/14 §1.6' },
  safetyFramework: { title: 'Safety framework', body: 'Your lab\'s own rules, modelled on the published frontier safety frameworks. Before any external release a model goes through [[evals]] (none / basic / full / deep, optionally read by external evaluators). Rules per domain on measured skill (Bio and Cyber: High holds launches without classifier safeguards, Critical without hardened ones and an external evaluation; AI research: Critical holds frontier training without a control protocol and human review on AI staff work) and on beliefs (if scheming, faking alignment or sandbagging could be above the line, the top of your range, frontier training is held: not knowing counts as risk). When a rule asks a product or your AI staff for safeguards, the framework adds them itself ([[agentControl|Framework safeguards]]; you pay their usual cost, and a part you remove is not put back). What safeguards cannot meet causes a Hold: a held launch is refused, a held product serves nobody, held training pauses. You may move a threshold a little, add requirements, or override a hold for one model: safety morale, a red flag, scrutiny and, if published, credibility.', src: 'SR-19; OpenAI Preparedness Framework v2 (2025), Anthropic RSP v2.2 (2025), Google DeepMind FSF v3 (2025)' },
  monitorability: { title: 'Monitorability', body: 'How readable the model\'s reasoning is (0–1). Latent reasoning and reasoning pressure lower it; chain-of-thought monitors only work while it is high.', src: 'research/14 §1.5' },
  sand: { title: 'Sandbagging', body: 'Deliberate underperformance on evaluations, mostly on dangerous-capability benchmarks. Makes measured skill read low.', src: 'research/04' },
  index: { title: 'Safety Index', body: 'A semiannual outside grade of every lab across risk assessment, current harms, frameworks, existential safety, governance and information sharing.', src: 'FLI AI Safety Index; research/17 §1.6.2' },
  distill: { title: 'Distillation', body: 'Training a cheaper model on another model\'s outputs. API access lets rivals and China distill you; KYC levels slow it.', src: 'research/12' },
  kyc: { title: 'KYC level', body: 'Buyer verification on API and Agents products (0–3). Distillers hide among anonymous buyers; each level verifies ten times more of them (half of API / Agents usage is anonymous at 0), so the [[distillLeak|leak]] through that product falls by about a quarter. A quarter of the buyers asked to verify leave instead (an estimate from the visitors UK sites lost when they added age checks, Ofcom 2025); the checks themselves cost too little to count.', src: 'V2-SPEC §3.3.5' },
  hype: { title: 'Hype', body: 'Investor appetite index for AI (1 = normal). Part of the market [[marketMood|mood]]: it moves the [[sectorValue|sector value]], so every lab\'s valuation and the [[investorPool|investor pool]]. Rises when the public frontier moves faster than expected, falls on shocks.', src: 'research/15 §1.4; FINANCE-V3 §1' },
  boardConf: { title: 'Board confidence', body: 'Board confidence 0–100. It drifts back toward 60 (a tenth of the gap each quarter) and moves only on four kinds of news, each weighted by the seats on your board: investor [[promise]] results (financial seats ×1.5, independents ×1, mission ×0.5), financial setbacks such as a [[downRound|down round]], a covenant breach or [[distress]] (independents ×1.5), falling behind the best rival (financial ×1.5, mission 0) and public incidents (mission ×2, financial ×0.5). It sways every seat in a [[boardVote|board vote]]. Below 35 the board warns you ([[boardWarning]]), below 25 it votes on removing you at every review ([[ouster]]); below 40 you can give the [[critics]] a seat.', src: 'FINANCE-V3 §7.4' },
  boardVote: { title: 'Board vote', body: 'Major decisions only: sale of control (a holder past 50%), a merger, a [[downRound|down round]], a [[rescue]], and firm commitments or debt that would exceed 3× revenue. Compute orders, releases, research and pricing are never voted on (only the [[charter]] can halt a release). Each voting seat leans by its stance on the decision, the outside owners\' drift, the board\'s [[boardConf|confidence]] and the situation (a short runway makes a board want money and fear new obligations; a merger, [[acquisition|buying a rival]], is judged on the runway after the deal); it votes yes above 0, your seat always votes yes. The vote passes with more than half the votes. No dice: the vote shown before you ask is the vote you get. With founder control (the founder board, or dual-class shares after an IPO) you can force a failed vote at board confidence −20.', src: 'FINANCE-V3 §7.3' },
  morale: { title: 'Morale', body: 'Staff morale 0–100. Scales productivity and attrition; safety staff morale reacts to safety decisions.', src: 'V2-SPEC §3.4.1' },
  M: { title: 'Research speed', body: 'See [[rdmult]].' },
  split: { title: 'Compute allocation', body: 'How your online compute is divided between uses: [[poolTraining|Training]], [[poolSynthetic|Data generation]], [[poolExperiments|Research experiments]], [[poolAgents|AI staff]], [[poolSafety|Safety work]], [[poolServing|Products]] and Safeguards. Set on Lab only; what no use draws on is [[idleCompute|idle]].', src: 'V2-SPEC §3.4.2' },
  wslTarget: { title: 'Security target', body: 'The [[wsl]] the security team builds toward; spending and siloing set the pace.' },
  ladderSec: { title: 'G-SEC ladder', body: 'Government security posture toward labs: 0 none, 1 briefings, 2 priority, 3 clearances, 4 oversight demands, 5 consolidation.', src: 'research/07 §1.1' },
  ladderChn: { title: 'China ladder', body: 'China\'s posture rung 0–6: coexistence, retaliation, acquisition, centralization, cyber operations, Taiwan pressure, war footing. The [[deesc|de-escalation track]] D1–D5 runs the other way.', src: 'research/10 §1.4' },
  sector: { title: 'Sector', body: 'One of 14 economic segments, each with its own [[workType|work type]], wage and employment. Firms hand tasks to AI ([[sectorA|automated share A]]) up to A* = [[feasibility]] × [[costGate|cost gate]] × (1 − [[friction]]); separately, [[workersUsingAI|workers use AI]] on the rest of their hours ([[hoursOfUse|hours of use]]). The [[binding]] limit is capability, cost, friction or diffusion.', src: 'research/16 §1A; research/22 §1; V4 and A2a notes' },
  paradigm: { title: 'Project', body: 'A big one-off capability idea on [[techTree|Discoveries]]: it either works or doesn\'t. Its [[odds|chance it works]] is shown before you start; whether it works is drawn per world. When it works it takes effect at once.', src: 'research/12 §0.7' },
  techTree: { title: 'Discoveries', body: 'One-off results that open new options, in six [[specialty|fields]]. An idea opens when you know what it needs; there are no capability gates. Researching it is a project for science teams.', src: 'TECH-TREE §1' },
  knowHow: { title: 'Know-how', body: 'What your lab knows about training and serving models, in five [[recipeStack|areas]] (Pretraining recipe, Post-training method, Post-training ceiling, Training efficiency, Serving efficiency), each shown as × its own quantity vs Jul 2025, plus [[otherEffects|domain effects]]. A new model builds in the know-how of its start; what it lacks is [[trainedIn|waiting]].', src: 'MODEL-V3 §5' },
  trainedIn: { title: 'Waiting', body: 'Know-how your newest model doesn\'t have yet ("×2.2 waiting"). A new pretraining run builds in the pretraining areas, a post-training run the post-training ones.', src: 'MODEL-V3 §3.1, §4.4' },
  depth: { title: 'Depth', body: 'Steps from what you know: depth 1 ideas need only known ideas; depth 2 need one more idea first, and so on.', src: 'TECH-TREE §1.1' },
  layer: { title: 'Takes effect', body: 'Where an idea takes effect: [[layerBackbone|new base model]], [[layerTraining|next post-training]], [[layerScaffold|a build]] (no training) or [[layerLab|at once]].', src: 'TECH-TREE §1.4' },
  layerBackbone: { title: 'New base model', body: 'Architecture, data, size: used by a new pretraining run, then post-training.', src: 'TECH-TREE §1.4' },
  layerTraining: { title: 'Next post-training', body: 'Post-training methods (reward training, alignment training, reasoning style): used by a post-training run on an existing base model.', src: 'TECH-TREE §1.4' },
  layerScaffold: { title: 'A build', body: 'At use time: product tools, memory, thinking effort, safeguards. No training needed; your engineers build it.', src: 'TECH-TREE §1.4' },
  layerLab: { title: 'At once', body: 'Research automation, instruments, efficiency practices: they take effect at once.', src: 'TECH-TREE §1.4' },
  effortClass: { title: 'Size', body: 'How much work a project is: small, medium, large or very large. Shown as the time to finish with your current staff; the team-weeks are in the breakdown. A safety programme shows months to its first result at [[seriousStaffing|serious staffing]] instead.', src: 'MODEL-V3 §5.3; design value' },
  teamMonth: { title: 'Team-month', body: 'One standard team for a month at the leading lab\'s Jul 2025 inputs: a science team for ideas, research engineers with their experiment compute for tests. Faster inputs do a team-month\'s work in less time. Breakdown tooltips only.', src: 'MODEL-V3 §5.3' },
  odds: { title: 'Chance it works', body: 'Your current odds a one-off project works in this world, from attempts so far. The result is drawn per world: if three ideas in a row are dropped, the project fails, and you can [[reopenSpeculative|retry it]] at lower odds. Programmes always produce results (each worth less). Safety ideas take their odds from their [[researchLine|programme]].', src: 'MODEL-V3 §5.3' },
  researchLine: { title: 'Programme', body: 'Ongoing research that keeps producing results, each worth less than the last. On safety, each finished project gives one result: a working instrument or method, a weaker one, a [[deadEnd|failure]], a discovery. How well it really works is hidden; you see its [[lineHealth|outlook]].', src: 'TECH-TREE §1.3, STRUCTURE §4.5' },
  lineHealth: { title: 'Outlook', body: 'Promising, Mixed or Struggling: whether this programme is likely to produce working results, from its results so far, with a range. The truth is hidden and differs by world.', src: 'STRUCTURE §4.5' },
  deadEnd: { title: 'Failed', body: 'A result that goes nowhere. The time spent on that attempt is lost, and the programme\'s outlook drops.', src: 'STRUCTURE §4.5' },
  seriousStaffing: { title: 'Serious staffing', body: 'About four matching safety science teams on a programme. At serious staffing a programme gets its first result in its listed months; more teams find ideas faster (with falling returns), research engineers and safety compute speed the tests, and [[trustedToAI|AI staff]] speed both.', src: 'TECH-TREE §4' },
  followUp: { title: 'Follow-up', body: 'The ongoing part of a programme once its ideas are known: more results (sharper instruments, measured evidence, discoveries, or failures).', src: 'STRUCTURE §4.5' },
  validation: { title: 'Validate', body: 'Plant a known trait in a test copy of a model and count how often an instrument finds it (found 14 of 20): its measured [[halfStrength|reliability]] on that model, with a range. Moving an instrument to a new model is the same job. It takes safety research engineers ([[safReNeeds|their needs]]) and some safety compute; a standing policy validates every instrument on each new internal model. Validation measures reliability; only research raises it.', src: 'SAFETY-REDESIGN §3.2' },
  caseStaffing: { title: 'Case staffing', body: '5–40 safety research engineers per case. More people (and AI help) finish it sooner; while the case runs (at most 120 days) it comes before [[validation|validations]] in the default order.', src: 'V2-SPEC §3.5.8' },
  specialtyBonus: { title: 'Field bonus', body: 'A science team works ×1.5 on ideas in its own field, ×1.0 elsewhere.', src: 'TECH-TREE §5 T2' },
  diminishingReturns: { title: 'Returns falling', body: 'More teams on one project help less each: two teams are about 1.4× one team, so spreading teams over projects often beats piling them on one.', src: 'TECH-TREE §1.2' },
  projectQueue: { title: 'Priority list', body: 'All your research, capability and safety, in priority order. Science teams go down the list (each project up to its [[teamsWanted|teams wanted]], best field first), research engineers and experiment compute go to the projects in tests in this order, and the rest waits. Drag, ▲▼, or Alt+↑ / Alt+↓ on a focused row to reorder.', src: 'MODEL-V3 §5.6' },
  autoAssign: { title: 'Safety team placement', body: 'Safety science teams are placed like capability teams: down the [[projectQueue|priority list]], each safety project up to its teams wanted; spare teams go where they add the most. With no safety project on the list they stay idle and Safety flags them. A finished project frees its teams; the programme\'s next project waits until you add it.', src: 'SAFETY-REDESIGN §3.1, §5' },
  // ── race / top strip ──
  evaluating: { title: 'Testing', body: 'A finished model is still in its [[evals]] (at the [[safetyFramework|Safety framework]] depth; it takes as long as the research engineers on evals need). Until it ends, the skill shown is the lineage\'s last measured one, and the model cannot be used or launched.', src: 'MODEL-V3 §10, V2-SPEC §3.3.5' },
  catRisk: { title: 'Catastrophe risk estimate', body: 'Your believed chance of catastrophe on today\'s path: the [[riskSource|risk sources]] combined. Built from your beliefs and intel, never the truth, so it is shown as a range.', src: 'V2-SPEC §6.6' },
  riskSource: { title: 'Where risk comes from', body: 'One path to catastrophe: your own models, each rival, China, misuse (bio, cyber), theft, rogue copies, war. Each row has a range, its drivers and the levers that reduce it.', src: 'V2-SPEC §6.6' },
  reliableAgent: { title: 'Reliable agent', body: 'Your models can do 50% of software-engineering work alone ([[coverage|can do alone]]). Opens Act 2.', src: 'MODEL-V3 §6.4; V3 notes' },
  researchAgent: { title: 'Research agent', body: 'Your models can do 50% of experiment work alone ([[coverage|can do alone]]). Opens Act 3 and [[automateSafety|AI safety work]].', src: 'MODEL-V3 §6.4; V3 notes' },
  milestone: { title: 'Milestone', body: 'A statement about [[workType|work types]]: agent and reliable agent (10% and 50% of software work done alone), research agent (50% of experiment work), [[sc]], [[sar]], [[siar]], [[asi]]. A lab crosses it when any of its live models, internal ones included, meets it; rollbacks never undo it. Lab › AI staff & needs shows how far each criterion is.', src: 'MODEL-V3 §6.4' },
  intelError: { title: 'Intel uncertainty', body: 'The ± on a [[lead]] estimate, in days. It shrinks with evidence: public releases, evaluator access, known incidents and thefts.', src: 'V2-SPEC §3.10.3' },
  act: { title: 'Act', body: 'Pacing stage that unlocks panels. 1 Startup; 2 Frontier race at a measured capability of 6.5 levels or day 150; 3 Automation at 8.5 levels; 4 Takeoff at 12 levels or [[rdmult|research speed]] ×25. Turning the tutorial off unlocks everything.', src: 'V2-SPEC §1.5, §6.8' },
  watch: { title: 'Watch list', body: 'Up to four problems found by rules on what you can see: idle chips, capped deployments, weak detection, runway, stale evals, board, morale. Each shows cause → effect and a Go button to the fix.', src: 'design/ux/IA.md' },

  // ── money ──
  cash: { title: 'Cash', body: 'Money in the bank ($B). Every inflow and outflow is booked and explained. If cash stays below zero for 30 days with no options left, you are insolvent.', src: 'V2-SPEC §3.7.6' },
  liquidity: { title: 'Liquidity', body: 'What [[runway]] counts as available: cash + the undrawn [[revolver]]. The revolver drops out in [[distress]]. Unconditional tranches enter the forecast in the quarter they land.', src: 'research/15 §1.8' },
  burn: { title: 'Burn', body: 'Gross spending per quarter: [[opex]], [[ledger]] commitments, chip balances and site [[capex]] falling due.', src: 'research/15 §1.8' },
  netBurn: { title: 'Net burn', body: '[[burn|Burn]] minus revenue, per quarter, averaged over the next 4 quarters of the [[runway]] forecast. Zero or negative means you are self-funding.', src: 'research/15 §1.8' },
  revenueNow: { title: 'Revenue now', body: 'One product\'s revenue today, annualised ($B/yr): demand served at its price. Product cards and edit previews show it; the top strip shows the [[revenueRun|30-day average]] of all products, which trails it.', src: 'V2-SPEC §3.11.3' },
  revenueRun: { title: 'Revenue run-rate', body: 'Revenue annualised and averaged over 30 days ($B/yr), the figure in the top strip. Drives [[valuation]] and the [[investorPool|investor pool]]; the Adoption [[roundMilestone|milestone]] is measured on it.', src: 'V2-SPEC §3.7.2, §3.11.3' },
  valuation: { title: 'Valuation', body: 'What investors think the company is worth: the [[sectorValue|sector value]] × [[storyShare|your share]] of it, marked each quarter (the mark moves half-way from the last one to today\'s story), at most your [[valuationCap|valuation cap]]. Each priced round resets it to the post-money until the next mark.', src: 'FINANCE-V3 §1; FIN6a' },
  // FIN5a: the story (FINANCE-V3 §1): sector value × share, the four drivers, the mood, supplier terms.
  sectorValue: { title: 'Sector value', body: 'What investors will pay for all private frontier labs together: κ × (their revenue run-rate)^0.7 × a frontier factor (the best public model\'s level ÷ 5)^0.75 × the market [[marketMood|mood]]. The labs\' valuations add up to less when some sit at their [[valuationCap|valuation cap]]: the real private labs\' marks summed to ≈ $0.5T in Jul 2025 and ≈ $2.5–3T in late 2026. Big-tech in-house labs are not in it.', src: 'FINANCE-V3 §1; research/15 §2.9' },
  marketMood: { title: 'Market mood', body: '[[hype|Hype]] × the [[rates]] factor (exp(−0.12 × (10-year yield − 4.5))) × 0.7 during a [[bubble|bust]]. It moves the [[sectorValue|sector value]] and with it every valuation and the [[investorPool|investor pool]].', src: 'FINANCE-V3 §1; research/15 §1.4' },
  storyShare: { title: 'Your share (the story)', body: 'Your part of the [[sectorValue|sector value]]: your weight ÷ the weights of all private labs. Weight = [[investorCred|credibility]] × [[govFactor|governance]] × exp(story score ÷ 1.25); the score sums four drivers, each measured against the rival field: [[storyPosition|position]] ×0.4, [[storyMomentum|momentum]] ×0.25, [[storyEconomics|economics]] ×0.1, [[storyCapacity|capacity]] ×0.25. Each quarter the mark moves half-way to today\'s share.', src: 'FINANCE-V3 §1' },
  storyPosition: { title: 'Position', body: 'Your best public model\'s level against the best rival public model (any lab, big tech included), per 2 levels, at most ±3. A lab with no public model is placed at the best open-weight model. The main driver: what markets can see.', src: 'FINANCE-V3 §1' },
  storyMomentum: { title: 'Momentum', body: 'Your revenue run-rate now ÷ four quarters ago (×0.5–×8), in doublings against the rival field\'s average. A pre-revenue lab counts ×1 (no growth, no penalty beyond that).', src: 'FINANCE-V3 §1' },
  storyEconomics: { title: 'Economics', body: 'Your serving gross margin, (serving revenue − serving compute cost) ÷ serving revenue, per 20 points against the rival field. Rivals\' margins are not public: they count at the sector\'s typical 50%. A pre-revenue lab counts at the field\'s.', src: 'FINANCE-V3 §1, §12' },
  storyCapacity: { title: 'Capacity', body: 'Compute you have secured (online plus contracted for the next 8 quarters), in doublings against the rival field\'s average.', src: 'FINANCE-V3 §1' },
  govFactor: { title: 'Governance factor', body: 'How investors price your governance (multiplies your weight in the [[storyShare|share]]): legacy capped-profit nonprofit ×0.6, nonprofit-controlled PBC ×0.9, PBC + trust ×1, founder-controlled ×1.1; ×0.95 more with [[dualClass|dual-class shares]]. Private rivals by kind: the safety lab PBC + trust ×1, the maverick and the boutique upstart founder-controlled ×1.1, the simulated leader lab a nonprofit PBC ×0.9.', src: 'research/15 §1.6; FINANCE-V3 §1, §12' },
  rivalValuation: { title: 'Rival valuation', body: 'A private rival is valued like you: the [[sectorValue|sector value]] × its [[storyShare|share]], marked each quarter (half-way from its last mark), at most its [[valuationCap|valuation cap]]. Its share reads the same four drivers; its [[investorCred|credibility]] comes from one rule (revenue up over four quarters, or pre-revenue: Credible ×1; down: Unproven ×0.9; halved: Doubted ×0.7), its [[govFactor|governance]] from its kind. When its cash falls under half a year of spend it raises at that valuation, at most 8% of the lab and its part of the [[investorPool|investor pool]] (the rivals\' parts and yours never add up to more than the pool). A lab that runs out of money is offered to you ([[acquisition|merger offer]]); still failing a quarter later, it is license-and-hired by the largest big-tech rival, or goes bankrupt when there is none.', src: 'FINANCE-V3 §12; FIN5b' },
  valuationCap: { title: 'Valuation cap', body: 'The most investors pay for any private lab, you included: the larger of $30B of team value (a pre-revenue frontier team: SSI $32B, Thinking Machines $12B) and a multiple of its revenue run-rate that rises with growth, 37× at ×5 a year × (growth ÷ 5)^0.4 (growth read at ×0.5–×8), so a slower or trailing lab trades lower. The share alone has no revenue-size term: without the cap a lab whose revenue collapsed would keep a few percent of a sector others\' revenue built.', src: 'research/21 A8; research/15 §1.5, C11; FIN5b, FIN6a' },
  supplierTerms: { title: 'Supplier terms', body: 'Chip suppliers ask a buyer that investors fund less, or with a short runway, to pay more upfront: a batch\'s deposit is 30% plus up to 35 points for a small [[storyShare|share]] (none from 25%) and up to 35 points for a short [[runway]] (none from 6 quarters). Supply contracts, a partner\'s included, prepay the same extra on their first delivery.', src: 'FINANCE-V3 §5' },
  capex: { title: 'Capex', body: 'Capital spending: chips (deposits and balances on delivery) and site construction by stage. Chips dominate; compute costs dwarf payroll.', src: 'V2-SPEC §3.7.6' },
  opex: { title: 'Opex', body: 'Running costs outside the [[ledger]]: [[payroll]], security spend, power and O&M, interest, spot rentals, revenue shares and the transition fund.', src: 'V2-SPEC §3.7.6' },
  payroll: { title: 'Payroll', body: 'Staff cost, paid monthly, per person-year: engineers $0.70M; research engineers $0.80M (safety $0.65M); scientists $1.00M (safety $0.80M); × [[teamQuality|quality]] (Solid 0.8, Strong 1, Elite 1.6). People already hired into a [[hiringQueue|queued team]] are paid. Small next to compute.', src: 'research/19 §1.2' },
  dilution: { title: 'Dilution', body: 'The share of the company a round sells: amount / post-money. Every holder shrinks pro rata. Rounds above 10% need board approval.', src: 'research/15 §1.5' },
  dilutionCap: { title: 'Dilution cap', body: 'Most one round may sell: 8% to financial investors, 14% with an [[anchorPartner|anchor partner]], 5% at an [[ipo|IPO]]. One limit of the [[raiseCeiling|raise ceiling]].', src: 'research/15 §1.5' },
  investorPool: { title: 'Investor pool', body: 'Money investors put into private frontier labs a year: 15% of the [[sectorValue|sector value]] (more while the [[ipo|IPO]] window is open), split by [[storyShare|each lab\'s share]]. Your part is your share of a quarter of it; what you leave unused carries over at 50%.', src: 'FINANCE-V3 §2.1; research/15 §1.4' },
  anchorPartner: { title: 'Anchor partner', body: 'A strategic investor taking at least 40% of a round. Raises the [[dilutionCap|dilution cap]] to 14%. Each partner anchors only one lab at a time; a hyperscaler only while its stake stays at or under 15%.', src: 'V2-SPEC §3.7.3–3.7.4' },
  repricedRound: { title: 'Repriced round', body: 'At close, investors marked your round more than 25% below its term sheet and below the last post-money. You choose: accept it as a [[downRound|down round]] (cash, dilution, board confidence −15) or pull it (no cash). Undecided after 30 days, it is pulled.', src: 'research/15 §1.5' },
  downRound: { title: 'Down round', body: 'A round priced below the last post-money. The distress round is offered only when runway is [[tight]] or in [[distress]], at 50–70% of value; a [[pitch|conservative pitch]] can also price one. A major decision: the board votes on it ([[boardVote]]), and approves more readily the shorter your runway. Board confidence −15 × the board\'s weight for setbacks, and anti-dilution shares for prior investors; no effect on staff.', src: 'research/15 §1.5, §1.8; FINANCE-V3 §2.5, §7.3' },
  rescue: { title: 'Strategic rescue', body: 'In [[distress]] a hyperscaler or sovereign tops its stake up to 30% for cash (about two quarters of burn, at least $20B, at most 15% of the valuation) and takes a board seat with two votes, [[exclusivity]] and [[ipAccess|IP access]] (when it has an in-house lab). The only way a partner gets a seat. A major decision: the board votes on it ([[boardVote]]), more readily the shorter your runway. At most one per year.', src: 'FINANCE-V3 §6.2' },
  recap: { title: 'Recapitalisation', body: 'Legacy-nonprofit preset only: restructure into a for-profit (about four quarters of attorney-general review, scrutiny up) to free a conditional growth tranche. Refusing cuts the tranche from $30B to $10B.', src: 'V2-SPEC §3.7.5' },
  ipo: { title: 'IPO', body: 'A one-time public listing while the IPO window is open and runway is healthy. It may sell only 5%, but taps a one-time public investor pool and adds a listing independent to the board. It carries no [[promise]]. With [[dualClass|dual-class shares]] founder votes keep control.', src: 'research/15 §1.5; FINANCE-V3 §2.6' },
  dualClass: { title: 'Dual-class shares', body: 'Listing with founder shares that carry extra votes (Anthropic\'s Class F: 50.1% of votes): you keep control after the [[ipo|IPO]] and can force a major decision past the board at a confidence cost, but governance-minded investors pay less: your weight in the [[storyShare|share]] ×0.95.', src: 'research/15 §1.6; FINANCE-V3 §1, §2.6' },
  roundMilestone: { title: 'Round milestone', body: 'What a round is raised on, due 12 months after it closes: Capability (a public model at a level), Scale (compute online that you own or hold on firm contracts, H100e; spot rentals and cancellable cloud do not count) or Adoption (a revenue run-rate). The target comes from your own trend over the last year, scaled by the [[pitch]].', src: 'FINANCE-V3 §2.2' },
  pitch: { title: 'Pitch', body: 'How hard you sell the round. Conservative: price ×0.85, target 0.8 × your trend\'s expected gain. Base: price ×1, your trend. Aggressive: price ×1.2, target 1.3 × the gain; needs Credible or Proven [[investorCred|credibility]], and a high price is the bar the next round must clear or be a [[downRound|down round]].', src: 'FINANCE-V3 §2.2' },
  promise: { title: 'Promise', body: 'Each priced round leaves one: its [[roundMilestone|milestone]] by the deadline. Promises stack and each is judged at its own deadline. Met: credibility +30 and board confidence +30 × the board\'s weight for promise results, × its weight; missed by more than 20% of the promised gain: −30 and −30 × the board\'s weight, × weight; in between nothing. Weight = the round\'s amount ÷ everything raised in the year to its deadline. An expectation, not a contract: never cash.', src: 'FINANCE-V3 §2.3–2.4' },
  promiseWeight: { title: 'Promise weight', body: 'A round\'s share of everything raised in the year to its deadline (this round and the later ones). A $1B round next to a $50B one barely counts; raising again before the deadline lowers it.', src: 'FINANCE-V3 §2.3' },
  neededByNow: { title: 'Needed by now', body: 'Where a [[promise]] should be today to arrive on time: the path from its start to its target (steady growth for compute and revenue, a straight line for model levels). More than 20% of the gain short of it after the first quarter reads "behind".', src: 'FINANCE-V3 §11' },
  investorCred: { title: 'Investor credibility', body: 'Whether investors believe your promises, 0–100, on four rungs: Doubted < 25 ≤ Unproven < 50 ≤ Credible < 75 ≤ Proven. Only [[promise|promises]] judged at their deadlines move it. It multiplies your weight in the [[storyShare|share]] of the sector value (×0.7 / ×0.9 / ×1 / ×1.15) and Aggressive [[pitch|pitches]] need Credible or better. Not the public [[credibility]] of your safety claims.', src: 'FINANCE-V3 §1, §2.4' },
  whatWeOwe: { title: 'What we owe', body: 'Every expectation and condition on the company in one place: live [[promise|promises]] with progress, tranche conditions, [[covenant|covenants]] with headroom and [[contingentLiability|contingent liabilities]].', src: 'FINANCE-V3 §0.4, §11' },
  contingentLiability: { title: 'Contingent liability', body: 'Money owed only if something happens: [[rvg|residual-value guarantees]] on leases (if you walk away) and copyright litigation over unlicensed training data (a suit settles automatically; licensing the data clears it).', src: 'FINANCE-V3 §4, §10' },
  trancheCondition: { title: 'Tranche condition', body: 'A contractual condition on the rest of a large round or a partner deal: revenue, GW online in your own sites (rented cloud does not count), an IPO or the recapitalisation by a deadline. Missed, that tranche lapses (the recapitalisation one is cut to $10B). A round of $20B or more (not an IPO or a distress down round) pays half at the close and half as such a tranche; its shares are issued at the close and those of money that lapses are cancelled. A partner\'s tranche buys shares at the valuation of the day it lands; a hyperscaler\'s only up to its 15% cap.', src: 'FINANCE-V3 §6.3' },
  ownership: { title: 'Ownership', body: 'Who holds the company: founders and staff, the mission entity, financial investors, strategic partners and the public. Outside ownership pushes the board toward speed and returns.', src: 'V2-SPEC §3.7.2, §3.7.4' },
  boardSeat: { title: 'Board seat', body: 'A vote on major decisions ([[boardVote]]), weighted by seat. Each seat has a stance on speed, finance, safety and mission, and its kind sets how much each kind of news moves its [[boardConf|confidence]]. Partners hold no seats except after a [[rescue]]; a partner\'s exclusivity (not a seat) blocks deals with its competitors.', src: 'V2-SPEC §3.7.4–3.7.5; FINANCE-V3 §7.3–§7.4' },
  boardWarning: { title: 'Board warning', body: '[[boardConf|Board confidence]] below 35 at a quarterly review. It clears back at 45. Without a warning at least 60 days old, no [[ouster]] vote is held.', src: 'V2-SPEC §3.7.5' },
  critics: { title: 'Give the critics a seat', body: 'Below 40 [[boardConf|confidence]], once a year: the side driving the decline gets a new director for good: a mission (safety) director if public incidents caused most of the last year\x27s losses, otherwise an investor director (falling behind, missed promises, financial setbacks). Confidence +15 now; from then on the seat votes and weighs news its way, including in an [[ouster]] vote (OpenAI added directors in Mar 2024; activist settlements).', src: 'FINANCE-V3 §7.5' },
  charter: { title: 'Charter rights', body: 'The few hard rights a governance preset gives its board, beyond [[boardVote|votes]]. Nonprofit-controlled PBC: the safety committee halts the release of any model your own evals red-flag (scheming, alignment faking or sandbagging believed above 50%: stricter than the 30% red-flag alarm) until the estimate falls. PBC + trust: the trust votes on a sale of control and on releasing the weights of a capability-threshold model (a bio, cyber or replication flag): its mission stance votes no on both, and it cannot be forced. Founder board or dual-class: you can force a failed board vote (−20 confidence). Legacy nonprofit: the board removes a CEO twice as easily (half the reluctance in an [[ouster]] vote).', src: 'FINANCE-V3 §7.2' },
  ouster: { title: 'Ouster', body: 'With confidence below 25 and a [[boardWarning|warning]] at least 60 days old, the board votes on removing you at every quarterly review, seat by seat and without dice; more than half the votes (your seat does not vote) ends the game. Each seat leans by its grievance (the last year\x27s losses read as too slow, too reckless or burning the company, against its stance), plus how far confidence is below 25, minus its reluctance (1.5; the legacy nonprofit board 0.75). The Board card shows the vote and where each seat turns before the review.', src: 'FINANCE-V3 §7.5' },
  ledger: { title: 'Commitment ledger', body: 'Contracted payments by quarter: cloud, chip supply, colocation and [[spv|financing leases]], power and acquired contracts. Each is [[firmCommit|firm]] or [[cancellable]]. Firm contracts pay one entry per quarter on the [[expectedPath|expected path]]. Commitments above 3× revenue need the board.', src: 'V2-SPEC §3.7.6; FINANCE-V3 §5' },
  firmCommit: { title: 'Firm commitment', body: 'A take-or-pay contract: you owe every payment whatever happens. Priced on the [[expectedPath|expected market path]] less a [[firmDiscount|firm discount]], and served first when chips are short. It counts in [[runway]] and the [[rating]].', src: 'research/15 §1.8; FINANCE-V3 §5' },
  cancellable: { title: 'Cancellable', body: 'A commitment you can exit with notice (in quarters). Cancellable cloud is indexed to the spot [[rental|rental rate]] × 1.15 and re-priced every quarter; in a chip shortage new cancellable capacity is rationed. In distress you can cancel to cut burn.', src: 'research/15 §1.8; FINANCE-V3 §5' },
  covenant: { title: 'Covenant', body: 'A lender\'s test each quarter end. A drawn [[revolver|credit line]] needs cash ≥ ⅓ of the line; [[gpuTerm|chip loans]] need chip value ≥ 1.2× the loan or cash is swept. A breach means [[distress]].', src: 'research/15 §1.7; FINANCE-V3 §3' },
  rating: { title: 'Credit rating', body: 'BBB, BB, B or closed, from a score: +2 if operating cash flow over the last year is positive, + liquidity ÷ this quarter\'s fixed payments (max 2), − (debt + 0.3 × firm commitments) ÷ revenue, − 2 in distress. BBB ≥ 2 > BB ≥ 1 > B ≥ 0. It prices the credit line, chip loans, bonds and [[spv|leases]]; closed shuts the credit line, bonds and leases.', src: 'FINANCE-V3 §3' },
  revolver: { title: 'Credit line', body: 'A committed bank line: 3% of [[valuation]], at most $15B, re-sized when you borrow on it or close a round (it does not grow by itself). SOFR + 1.5–2.5% by [[rating]]. Draw and repay freely; it covers negative cash automatically. Frozen in [[distress]]; [[covenant]]: cash ≥ ⅓ of the line.', src: 'research/15 §1.7; FINANCE-V3 §3 (OpenAI $4B, Anthropic $15B)' },
  gpuTerm: { title: 'Chip-backed loan', body: 'A 4-year loan secured on your chips: up to 60% of their value (chips count at 70% of today\'s list price), SOFR + 4–5.5% by [[rating]]. The only debt open to a loss-making lab. If chip value falls below 1.2× the loan, cash is swept to pay it down.', src: 'research/15 §1.7 (CoreWeave DDTL)' },
  assumed: { title: 'Assumed debt', body: 'Debt that came with a lab you bought: the cash it was short when it ran out of money. Its lenders re-price it to your [[rating]] (10-year yield plus your bond spread); it runs three years, then rolls like a bond. Repay it any time.', src: 'FINANCE-V3 §9' },
  acquisition: { title: 'Buying a rival', body: 'A private rival that runs out of money is for sale at about half its valuation, for cash or your stock (new shares at your valuation: its holders get price ÷ (your valuation + price)). You get 70% of its staff and take on its contracts (one [[firmCommit|firm]] entry: its spend a year, for two more years) and its debt ([[assumed|assumed debt]]): the real risk of buying a failing lab. Antitrust scrutiny rises. A merger needs the [[boardVote|board]], judged on the company after the deal; paying in stock that hands its holders more than half the company is also a sale of control (the trust votes too, and if it goes through you no longer run the company). A government consolidation (DPA) brings the contracts and debt of every private rival the same way, with no price. Declined, a lab still failing next quarter is license-and-hired by the largest big-tech rival (its models licensed, most of its team hired, its compute moved; its investors get about 1.25× their money back), or goes bankrupt when there is no big-tech rival.', src: 'FINANCE-V3 §9, §12; FIN3c, FIN5b' },
  bond: { title: 'Bond', body: 'Ten-year debt at the 10-year yield plus a [[rating]] spread. Only while operating cash flow over the last year is positive, up to 3× it.', src: 'FINANCE-V3 §3' },
  spv: { title: 'Financing lease', body: 'A lease of capex (through a special-purpose vehicle, SPV): a lessor pays it and you pay funded × CRF(r, n) a year: r by [[rating]] (BBB 7%, BB 9%, B 12%; below B only with a hyperscaler or chip-vendor [[deal|partner]] guarantee, at 15%), n = 15 years for a site (80% funded) or 5 for chips. It changes timing, not cost (its [[presentValue|present value]] is close to paying cash), and adds a long [[firmCommit|firm]] obligation. [[rvg|Residual-value guarantee]]: half the unpaid balance if you walk away.', src: 'FINANCE-V3 §4 (Meta–Blue Owl Hyperion 80/20)' },
  rvg: { title: 'Residual-value guarantee', body: 'A contingent liability of a [[spv|lease]]: 50% of the unpaid balance if you walk away from the asset. Owed only then.', src: 'FINANCE-V3 §4' },
  payOption: { title: 'Payment option', body: 'How capex is paid: cash on the build or delivery schedule, a [[spv|lease]] (a lessor pays; you pay it back with its return over the asset life), or for chips a [[gpuTerm|chip-backed loan]]. Each shows its total over the asset\'s life and its [[presentValue|present value]]; compare on the present value, since a lease always has the larger total.', src: 'FINANCE-V3 §4' },
  presentValue: { title: 'Present value (PV)', body: 'Every payment of an option discounted to today, so that paying later counts for less: a payment q quarters away counts ÷ (1 + r)^(q/4). r is the lessor\'s return at your [[rating]] (what borrowing against the asset costs you), or the chip-loan rate when no lessor funds you; the tile\'s tooltip says which. A [[spv|lease]] discounted at its own rate comes out close to cash: it moves payments later, it does not make the asset dearer.', src: 'FINANCE-V3 §4' },
  parentAdvance: { title: 'Advance from the parent', body: 'A division\'s cash below zero: it spent past its [[parentBudget|budget]] and the parent paid the bills. Not a debt and no interest: the parent\'s next budget payments repay it first, and overspend the parent is still covering at a [[parentReview|review]] costs [[parentConf|parent confidence]].', src: 'FINANCE-V3 §13' },
  exclusivity: { title: 'Exclusivity', body: 'An optional string on a hyperscaler or chip-vendor deal: the partner pays 25% more and you sign no deal with its competitor, for good. One deep partner (more money, locked in) or several shallow ones (independence, less money each). Always part of a [[rescue]].', src: 'FINANCE-V3 §6.1 [D]; research/21 §3.2' },
  ipAccess: { title: 'IP access', body: 'An optional string on a hyperscaler deal: the partner pays 20% more and its in-house lab (a big-tech rival) licenses your models while the deal runs, closing about 10% of your capability lead a year. Part of a [[rescue]] when the partner has a lab. Under a PBC + trust [[charter]], licensing a capability-threshold model needs a yes from the trust.', src: 'FINANCE-V3 §6.1 [D]; research/21 B4 (FTC: "a bridge until our own model is competitive")' },
  deal: { title: 'Strategic partner', body: 'Up to 3 partners at once, one deal each, its terms priced today and shown in full before you sign. Hyperscaler: non-voting equity now and in two [[trancheCondition|tranches]] (its stake stays at or under 15%, no board seat) plus cloud capacity or custom chips against a [[firmCommit|take-or-pay]] commitment, priced on the [[expectedPath|expected path]] less the [[firmDiscount|firm discount]] and its own 10%, with an 8% revenue share while it runs; optional [[exclusivity]] and [[ipAccess|IP access]] add money. A running hyperscaler or chip-vendor partner guarantees your [[spv|leases]] below rating B. Chip vendor: $10B of equity per GW you bring online, for buying its chips on the path (5% off), with +0.5 [[allocation]] weight while it supplies. Sovereign: a passive cheque; scrutiny, Congress trust and security demand pay for it. In distress only a [[rescue]] is on offer.', src: 'FINANCE-V3 §6; research/21 B2–B4' },
  bubble: { title: 'Bubble', body: 'Pressure X = sector commitments and capex / sector revenue. Above 3 a bust gets likely (up to 12% per quarter): for a year the [[sectorValue|sector value]] (so valuations and the investor pool) ×0.7, hype crashes, credit spreads widen.', src: 'research/15 §1.4' },
  rates: { title: 'Rates', body: 'The 10-year yield (y10, a random walk around 4.5%) and SOFR (y10 − 0.3). Higher rates shrink valuations and the investor pool. Loans price over SOFR, bonds over y10.', src: 'V2-SPEC §3.7.4' },
  distress: { title: 'Distress', body: 'Runway under 3 quarters or a covenant breach. Credit line frozen, no priced rounds, debt +3%; the board minds each review in distress. No effect on staff. Options: [[downRound|down round]], [[rescue]], renegotiate, sell chips, cancel contracts.', src: 'research/15 §1.8' },
  tight: { title: 'Tight', body: 'Runway of 3–6 quarters. Investors offer 20% less, board confidence −5 a quarter, and the distress menu opens early. Fast-forward stops when you enter it.', src: 'research/15 §1.8' },
  healthy: { title: 'Healthy', body: 'Runway of 6 quarters or more. Full access to the investor pool and credit.', src: 'research/15 §1.8' },

  // ── compute ──
  computeOnline: { title: 'Compute online', body: 'H100e you can use today: chips installed in live sites (limited by [[mw|MW]]) plus cloud contracts and spot rentals. Divided between uses by the [[split|compute allocation]].', src: 'V2-SPEC §3.8' },
  idleChips: { title: 'Unracked chips', body: 'Delivered chips with no rack space: every live site is full. They earn nothing and lose 6% of their value each quarter until new [[mw|MW]] goes live. Chips that fit are [[installing]], not unracked.', src: 'research/15 §1.3' },
  listPrice: { title: 'List price', body: 'Price per H100e of chips ($K): chip cost × supplier markup, plus a premium when demand outruns supply. Cost falls about 8% a quarter; orders pay the [[expectedPath|expected]] list price of their delivery quarter.', src: 'research/15 §1.2' },
  spotPrice: { title: 'Spot price', body: 'Price of a spot chip order: [[listPrice|list price]] plus half the shortage premium. No deposit, delivered next quarter, lowest priority in rationing.', src: 'research/15 §1.2' },
  rental: { title: 'Rental rate', body: 'Spot cloud price per H100e-hour: 1.6 × owned cost, rising with demand/supply. A one-quarter spot rental pays it and is capped at 10% of the rental pool; [[cancellable]] cloud pays it × 1.15.', src: 'research/15 §1.2' },
  cloudContract: { title: 'Cloud contract', body: 'Rented capacity from next quarter, no MW of your own. [[firmCommit|Firm]]: take-or-pay at the [[expectedPath|expected cloud price]] each quarter less a [[firmDiscount|firm discount]], served first in a shortage. [[cancellable|Cancellable]]: spot-indexed × 1.15, one quarter\'s notice.', src: 'research/15 §1.2; FINANCE-V3 §5' },
  lta: { title: 'Chip supply contract', body: 'Chips every quarter for 1–4 years from two quarters after signing, take-or-pay through the [[ledger]]: each tranche is priced at the [[expectedPath|expected list price]] of its quarter less a [[firmDiscount|firm discount]]. Firm orders get +0.5 [[allocation]] weight.', src: 'research/15 §1.2; FINANCE-V3 §5' },
  expectedPath: { title: 'Expected path', body: 'The market forecast contracts are priced on: chip cost falls 8% a quarter and the shortage premium fades by a quarter each quarter (kW per chip falls too). A firm contract follows it: if prices fall faster or demand disappoints you overpay; in a shortage you are protected.', src: 'research/15 §1.2; FINANCE-V3 §5' },
  firmDiscount: { title: 'Firm discount', body: 'Price cut for committing: 5% on firm contracts of 2 years or more, 10% from 4 years.', src: 'FINANCE-V3 §5 [design value]' },
  allocation: { title: 'Allocation', body: 'When supply is short, orders are rationed. Fill share = what you got of last quarter\'s due orders. Order weight = 1 + 0.5 firm (take-or-pay) + 0.5 prepay + 0.5 while a chip partner supplies you (a chip vendor or custom chips) + 0.3 track record.', src: 'research/15 §1.2' },
  exportPolicy: { title: 'Export policy', body: 'US chip export controls: strict, case-by-case or open. Sets China\'s share of global chip supply (1% / 6% / 12%, plus smuggling) and so its compute.', src: 'research/15 §1.2; research/10' },
  taiwanRisk: { title: 'Taiwan risk', body: 'Most leading chips come from Taiwan (93% falling to 75%). A quarantine cuts supply for quarters, spikes prices and loses chips in transit. Odds rise with [[taiwanTension|tension]]. Non-Taiwan allocation costs 30% more.', src: 'research/15 §1.2' },
  packaging: { title: 'Packaging', body: 'Advanced chip packaging capacity (H100e per quarter). One of three supply components; global supply is the smallest of [[packaging]], [[hbm|HBM]] and [[wafer|wafers]]. Expands in about 4 quarters.', src: 'research/15 §1.2' },
  hbm: { title: 'HBM', body: 'High-bandwidth memory capacity. One of three supply components; about 6 quarters to expand. Exposed to Korea disruption.', src: 'research/15 §1.2' },
  wafer: { title: 'Wafers', body: 'Leading-edge wafer capacity. The slowest supply component (about 16 quarters to expand); expected to bind later in the game.', src: 'research/15 §1.2' },
  mw: { title: 'MW', body: 'Facility power capacity of your sites. Chips run only where there is power: H100e capacity = MW × 1000 / [[kwPerH100e]].', src: 'research/15 §1.3' },
  kwPerH100e: { title: 'kW per H100e', body: 'Facility power each H100e of compute needs, including cooling. Falls every quarter as chips get more efficient, so the same MW holds more compute.', src: 'research/15 §1.3' },
  transformers: { title: 'Transformers', body: 'Large power transformers: 8–10 quarter lead time. Brownfield, grid and nuclear sites wait for them unless you pre-order (20% deposit).', src: 'research/15 §1.3' },
  gridPool: { title: 'Grid pool', body: 'New US grid capacity for large loads each quarter (starting 1.5 GW, growing 25%/yr), shared by everyone. Grid sites need a slot; when it runs out they slip a quarter.', src: 'research/15 §1.3' },
  site: { title: 'Site', body: 'A data centre. Moves through [[permitting]] → power → construction → live (or blocked). Choose a [[siteTier|size]], a [[sitePath|power source]], [[crashBuild|crash build]], [[communityPackage|community package]] and a [[payOption|payment option]].', src: 'V2-SPEC §3.8' },
  sitePath: { title: 'Power source', body: 'Colo (lease): fastest, no block risk, network capex only. Brownfield: ≤ 1 GW, power in 4–8q. Gas: ≤ 2.5 GW, 6–12q, costlier power, more opposition. Grid: ≤ 5 GW, 12–24q, needs the [[gridPool|grid pool]]. Nuclear: ≤ 1 GW, 12–20q, cheap power.', src: 'research/15 §1.3' },
  permitting: { title: 'Permitting', body: 'The first site stage. At its end local opposition can block the site (capex spent is lost) or delay it 1–3 quarters. Odds rise with public data-centre opposition, gas and crash builds.', src: 'V2-SPEC §3.8' },
  crashBuild: { title: 'Crash build', body: 'Build in 4 quarters instead of 8, at +35% capex and higher block risk.', src: 'research/15 §1.3' },
  communityPackage: { title: 'Community package', body: 'Upfront, for a site still in permitting: +3% capex, halves the odds of being blocked. As the company default every new site gets it, with a pledge to pay your own power and grid costs. After a block, a large package (15% of capex, +2 quarters) unblocks with odds set by local opposition.', src: 'research/15 §1.3; research/17 F1; FINANCE-V3 §4' },
  installing: { title: 'Installing', body: 'Delivered chips that fit in free racks. They are racked and online at the start of next quarter.', src: 'research/15 §1.3' },
  emptyRacks: { title: 'Empty racks', body: 'Powered capacity in your live sites with no chips in it. You pay for the building and its upkeep; it adds no compute until chips arrive. Racks grow each quarter as [[kwPerH100e|kW per H100e]] falls.', src: 'research/15 §1.3' },
  poweredCapacity: { title: 'Powered capacity', body: 'The most compute you could run: H100e that fit in your live sites ([[mw|MW]] ÷ [[kwPerH100e|kW per H100e]]) plus [[cloudContract|cloud]] in force. Chips beyond it sit [[idleChips|idle]].', src: 'research/15 §1.3' },
  vendorFill: { title: 'Vendor fill', body: 'Share of your due chip orders the vendors delivered last quarter. Below 100% when supply is short and orders are rationed by [[allocation]] weight.', src: 'research/15 §1.2' },
  siteTier: { title: 'Data-centre size', body: 'Hall 100 MW (one AI data hall) · Building 300 MW · Campus 1 GW (the largest live sites in 2026) · Large campus 2.5 GW · Multi-GW campus 5 GW. Colo, brownfield and nuclear top out at a campus; gas at a large campus; only the grid reaches 5 GW.', src: 'Epoch AI data centers hub; research/15 §1.3' },
  colo: { title: 'Colo (colocation lease)', body: 'Lease racks in a third-party data centre: live in 1–3 quarters, no permits, no block risk. You pay network fit-out plus a 5-year lease (about 12%/yr of the facility). Limited by the colocation capacity on the market each quarter.', src: 'research/15 §1.3' },
  brownfield: { title: 'Brownfield', body: 'Reuse an industrial site with an existing grid connection: up to 1 GW, power in 4–8 quarters, needs [[transformers]].', src: 'research/15 §1.3' },
  gasPower: { title: 'Gas (on-site)', body: 'Your own gas turbines: up to 2.5 GW, power in 6–12 quarters, no grid queue. Power costs 1.3× grid and local opposition is likelier.', src: 'research/15 §1.3' },
  gridPower: { title: 'Grid', body: 'A new utility interconnection: up to 5 GW, but 12–24 quarters to power and a slot in the [[gridPool|grid pool]]. Needs [[transformers]].', src: 'research/15 §1.3' },
  nuclearPower: { title: 'Nuclear', body: 'Power from a nuclear plant (restart or co-location): up to 1 GW, 12–20 quarters, highest capex, cheapest power (0.8×).', src: 'research/15 §1.3' },
  pool: { title: 'Compute allocation', body: 'See [[split]]: one share per use (training, data generation, research experiments, AI staff by job, safeguards, safety work, products), the rest [[idleCompute|idle]].', src: 'V2-SPEC §3.4.2' },
  poolTraining: { title: 'Training', body: 'Compute your training runs draw on. It sets how fast runs finish; each run takes a [[poolShare|share]]. See [[trainingPool]].', src: 'V2-SPEC §3.3.1' },
  poolExperiments: { title: 'Research experiments', body: 'Compute for your teams\' small and big tests, capability projects included.', src: 'V2-SPEC §3.2.1' },
  poolAgents: { title: 'AI staff', body: 'Compute your [[agentPackage|AI staff]] run on, by job: engineering, experiments, ideas and safety, each its own share of the [[split|compute allocation]]. More compute runs more [[agentCopies|copies]] of the model on that job.', src: 'V2-SPEC §3.2.1, §3.4.2' },
  poolSynthetic: { title: 'Data generation', body: 'Compute your models spend writing training data. It builds the data new base models need; short of it, a base model re-reads its data more and gains less. It does not speed up research.', src: 'V2-SPEC §3.2.2, §3.3.2' },
  poolServing: { title: 'Products', body: 'Compute that serves your customers. Each product takes a [[servingShare|share]]; too little leaves demand [[capacityBound|unserved]].', src: 'V2-SPEC §3.11.3' },
  poolSafety: { title: 'Safety work', body: 'Compute for safety programmes, validations, cases and safety evals. Safety AI staff and [[runtimeMonitoring|safeguards]] have their own shares of the [[split|compute allocation]].', src: 'V2-SPEC §3.5.2' },
  poolResearch: { title: 'Research compute', body: 'Research experiments plus AI staff on experiments and ideas: the compute that speeds up your research.', src: 'V2-SPEC §3.4.2' },
  poolHumans: { title: 'Research staff', body: 'Your capability research engineers and scientists, the people working on your [[prodfn|projects]]. They matter less as AI staff do more of the work.', src: 'research/13 §1.3' },
  researchMix: { title: 'AI staff vs experiments', body: 'How your research compute is shared between [[poolExperiments|research experiments]] and [[poolAgents|AI staff]] on experiments and ideas. Each is its own share of the [[split|compute allocation]]; "What 10% more buys" shows which helps more.', src: 'research/13 §1.3' },
  responseCurve: { title: 'What 10% more buys', body: 'What moving 10% of compute or staff to each input would change in research speed, ranked. A big gain marks what [[bottleneck|limits]] you; a small one means more of it buys little.', src: 'research/13 §1.6' },
  safetyLoad: { title: 'Safety work', body: 'What safety staff and safety compute are doing: programmes, validations, cases, safety evals, safeguards, AI staff, and what is idle.', src: 'V2-SPEC §3.5.2' },
  safetyAgents: { title: 'AI staff: safety', body: 'AI copies doing safety research: the safety job of your [[agentPackage|AI staff]], on its own share of compute. Pick the model there: an older trusted one is weaker but carries its own, lower sabotage risk. [[trustedToAI|AI share allowed]] sets how much safety work they do.', src: 'STRUCTURE §4.9' },
  computeBound: { title: 'Limited by: compute', body: 'More experiment compute would speed research more than more research engineers (people or AI) would.', src: 'research/13 §1.6' },
  laborBound: { title: 'Limited by: research engineers', body: 'More research engineers, people or AI staff, would speed research more than more experiment compute would.', src: 'research/13 §1.6' },
  humanBound: { title: 'Limited by: scientists', body: 'Short of people: they still do most of the work that limits you ([[humanShare|humans\' share]] over 50%). Hire, or give your AI staff work they can do.', src: 'research/13 §1.6' },
  tasteBound: { title: 'Limited by: idea quality', body: 'Late: AI research taste drives most of your research speed, so which ideas get tried matters more than compute or staff.', src: 'research/13 §1.6' },
  experiments: { title: 'Experiment compute', body: 'Compute spent testing ideas. Research needs it alongside research engineers: AI staff without experiments hit a ceiling.', src: 'research/13 §1.2' },
  researchTaste: { title: 'Research taste', body: 'How good a team\'s research choices are, shown against your scientists ("like a top-5% scientist"). A team\'s taste is the better of its people (Solid, Strong, Elite, plus star hires) and the AI staff on ideas. Taste raises an idea\'s [[beliefBand|expected effect]] and makes the team surer of it.', src: 'research/13 §2.4; MODEL-V3 §8' },
  aiFte: { title: 'AI staff in people', body: 'Your AI staff\'s work in full-time people: their compute buys work-hours at the model\'s [[useHourCost|cost per hour of work]], over 2,000 hours a year.', src: 'research/20 D1–D2; MODEL-V3 §6.3' },
  agentCopies: { title: 'Copies', body: 'Parallel copies of the model at work at once (each about 5× a human\'s speed, at most 50×). Smaller or cheaper-to-serve models run more copies on the same compute.', src: 'research/20 D1; MODEL-V3 §6.3' },
  nextModelGate: { title: 'Next-model gate', body: 'What limits your next frontier pretraining run: [[trainingDays|training days]], data ([[dataWall|re-reads]]), free MW, or cash.', src: 'V2-SPEC §3.2.5' },
  dataWall: { title: 'Re-reads', body: 'A base model trains on a set number of tokens, drawn from your data by its [[dataMix|data mix]]; a domain drawn beyond its unique tokens is re-read. Up to about ×4 re-reads costs almost nothing; beyond that each re-read is worth less. More data (generated, licensed, usage) pushes it back.', src: 'MODEL-V3 §3.2; research/20 A3' },
  trainingDays: { title: 'Training days', body: 'Days your training compute needs to deliver a frontier-size pretraining run (the readout of the next-model gate). Runs have no maximum or minimum length.', src: 'V2-SPEC §3.2.5; MODEL-V3 §3.3' },

  // ── people / security ──
  headcount: { title: 'Headcount', body: 'People on your [[team|teams]]: capabilities (engineers, research engineers, scientists) and safety (research engineers, scientists).', src: 'STRUCTURE §4.1' },
  team: { title: 'Team', body: 'Staff come in whole teams of fixed size: [[roleEng|engineering]] 150, [[roleRE|research engineering]] 100, [[roleSci|science]] 40. Attrition leaves vacancies that hiring refills first.', src: 'STRUCTURE §4.1' },
  roleEng: { title: 'Engineers', body: 'Software, infrastructure and product engineers: they build and run products, tools, run setups, safeguards and launches. Output: [[buildCapacity|build capacity]]. Taken over by AI first.', src: 'research/19 §1.1' },
  roleRE: { title: 'Research engineers', body: 'They run experiments and keep training runs going. Safety research engineers validate instruments and run cases. Taken over by AI second.', src: 'research/19 §1.1' },
  roleSci: { title: 'Scientists', body: 'They choose and design research: capability science teams run the projects on [[techTree|Discoveries]] (×1.5 in their [[specialty|field]]); their quality sets [[researchTaste|research taste]]. Taken over by AI last.', src: 'research/19 §1.3' },
  teamQuality: { title: 'Team quality', body: 'Solid ×0.8 output at ×0.8 cost; Strong ×1 (the reference); Elite ×1.25 output at ×1.6 cost.', src: 'research/19 §1.2' },
  specialty: { title: 'Field', body: 'A science team\'s field: Pretraining, Post-training, Systems (capability) or Alignment, Interpretability, Evals & control (safety).', src: 'STRUCTURE §4.1' },
  buildCapacity: { title: 'Build capacity', body: 'How much engineering your engineers and [[engAgents|AI staff]] do per week. AI staff add the share of the work they [[coverage|can do alone]]; the rest limits the speed-up. Spent on the [[engNeeds|engineers\' needs]] in your order.', src: 'MODEL-V3 §6.3; V3.3' },
  engAgents: { title: 'AI staff: engineering', body: 'Your models coding for your engineers (Lab › AI staff & needs), on their own share of the [[split|compute allocation]]. They add to [[buildCapacity|build capacity]] through the share of software work they [[coverage|can do alone]].', src: 'MODEL-V3 §6.3' },
  runOps: { title: 'Run operations', body: 'Research engineers keeping training runs going (failures, restarts, data and checkpoint problems); a pretraining run needs the most, a distil the least. AI staff on experiments carry part of it. First in the research engineers\' needs by default. Short of it, every run slows to the share covered (half covered: half speed).', src: 'MODEL-V3 §3.3, §5 [Design]' },
  productUpkeep: { title: 'Upkeep', body: 'Engineering each live product, safeguard or tool needs every week: reliability, on-call, integrations and model swaps; it grows with revenue. A tool that is off on every product needs a tenth (Off, upkeep only). Served after runs; if it takes all the capacity, nothing new ships.', src: 'jank J2 [Design]' },
  keepHiring: { title: 'Hiring target', body: 'A policy per team kind: while you have fewer teams than this, a standard Strong team is queued and filled. It never lays anyone off; letting a team go lowers it.', src: 'STRUCTURE §4.1' },
  hiringQueue: { title: 'Hiring queue', body: 'Teams being filled. A team arrives, and starts working, when every seat is filled. Each department has one hiring lane at its [[weeklyHireCap|weekly rate]]; vacancies come first, then queued teams by how far each kind is behind.', src: 'research/19 §1.2' },
  teamOffer: { title: 'Team offers', body: 'Teams on the market: one new offer a week, each open for 4 weeks. Quality and field vary; hiring one queues it ahead of policy hires.', src: 'STRUCTURE §4.1' },
  moveTeam: { title: 'Move a team', body: 'Research-engineering teams switch between capabilities and safety in one click. Moving safety staff to capabilities costs 5 safety morale.', src: 'STRUCTURE §4.1' },
  weeklyHireCap: { title: 'Weekly hire rate', body: 'People hired per week per department: capabilities 15, safety 3, × [[talentPull|talent pull]] × morale.', src: 'V2-SPEC §3.4.1' },
  starHire: { title: 'Star hire', body: 'Recruit a top researcher for $0.3B: raises your scientists\' [[researchTaste|research taste]]. Annoys the rival you poach from.', src: 'V2-SPEC §3.4.1' },
  talentPull: { title: 'Talent pull', body: 'Your draw as an employer (−50..+50). Scales hiring speed and resistance to poaching. Published safety research and a good Index grade raise it.', src: 'research/17 §1.2' },
  siloing: { title: 'Siloing', body: 'Compartmentalising research (levels 0–2). Each level: research −5%, fewer staff with frontier access (spies ×0.7), morale −3.', src: 'V2-SPEC §3.6' },
  counterIntel: { title: 'Counter-intelligence', body: 'Insider-threat and detection programme (0–1). Raises the chance you detect a weight theft. Each step costs $0.1B/yr.', src: 'V2-SPEC §3.6' },
  privileged: { title: 'Privileged staff', body: 'Researchers with frontier access (capabilities + safety, reduced by [[siloing]]). Spies hide among them.', src: 'V2-SPEC §3.6' },
  theft: { title: 'Weight theft', body: 'China steals your best internal model, traits included. Possible once China\'s ladder reaches acquisition and you lead by over 90 days. Odds fall with [[wsl]], rise with [[theftIntent|theft intent]].', src: 'V2-SPEC §3.6' },

  // ── models ──
  base: { title: 'Base model', body: 'A pretrained model. Sets most of a model\'s capability and starts a lineage of traits. Models are post-trained from it; an old base model falls behind.', src: 'V2-SPEC §3.1.3–3.1.4' },
  version: { title: 'Model', body: 'A post-trained model built on a base model: the thing you test, put in use and run as AI staff. Has its own true skill, traits and measured evals.', src: 'V2-SPEC §3.1.4' },
  variant: { title: 'Model kind', body: 'Your own full model, a smaller distilled one (cheaper, weaker) or an imported open-weight model (internal use until post-trained). Government and Trusted are who a [[product]] is offered to, not kinds of model. Agents and Enterprise take full models.', src: 'V2-SPEC §3.3.5; RD-P05' },
  openRelease: { title: 'Release open weights', body: 'A one-way act on a model: its weights become public for good. China absorbs the know-how in it above the open frontier, rivals distil it at their next post-training, and anyone can fine-tune it, so misuse safeguards reduce to the hazard filter. The model stays yours to use and sell.', src: 'V2-SPEC §3.3.5; RD-P05' },
  internalAgent: { title: 'AI staff model', body: 'A model working inside your lab. Each [[agentPackage|AI staff]] job has its own model; the experiments model drives most of your [[rdmult|research speed]] and the internal incidents. Needs no release check.', src: 'STRUCTURE §4.9' },
  pretraining: { title: 'Pretraining', body: 'Trains a new base model on your [[dataTokens|data]] with [[trainingPool|training compute]]: the longest runs. A base model is then [[postTrain|post-trained]] into models you can use.', src: 'MODEL-V3 §3' },
  runForecast: { title: 'Run forecast', body: 'The level your lab expected a run to reach, taken at launch from what you believe about your methods and the measured start model, with its 90% range. [[evals|Evals]] of the result measure the real level; about 9 forecasts in 10 should hold it.', src: 'UB-2b; models/runs.ts runForecast' },
  postTrain: { title: 'Post-training', body: 'Turns a base model into a new model: [[rlBudget|post-training compute]] on your [[envSuite|environments]], using today\'s post-training know-how (the base model keeps its pretraining know-how). Choices: [[preference]], [[rlFocus|post-training focus]], [[rlBudget|post-training budget]], [[cot|chain of thought]], [[safetyTraining|safety training]].', src: 'MODEL-V3 §4' },
  baseRun: { title: 'Pretraining: new', body: 'Pretrain a new base model of a chosen [[activeParams|size]] and [[tokensPerParam|tokens per parameter]]. It builds in the [[knowHow|know-how]] of its start date (see [[behindAtFinish]]) and starts a fresh lineage. Its traits are pulled toward those of the AI staff doing your research, by their share of the work and how little of it your safeguards catch.', src: 'MODEL-V3 §3, §11.2; V2-SPEC §3.5.4' },
  continueRun: { title: 'Pretraining: continue', body: 'Extend an existing base model with about a third more training. Only the added part uses today\'s know-how. Keeps its lineage, traits and failure modes.', src: 'MODEL-V3 §3.4' },
  distillRun: { title: 'Distil', body: 'Train a smaller student (default an eighth of the teacher\'s size) on the teacher\'s outputs. It lands below the teacher by the [[distillGap|skill drop]] and is cheaper to serve. The student learns only what the teacher\'s outputs show: its visible traits in full, a small share of those that act only when unobserved (faking alignment, scheming, sandbagging), none of its training gaming.', src: 'MODEL-V3 §4.5; research/20 C4, F3; Cloud et al. 2025' },
  baseSize: { title: 'Size', body: 'A base model is set by its [[activeParams|parameters]] and [[tokensPerParam|tokens per parameter]]. Bigger trains longer ([[wallTime|time]]) and falls further [[behindAtFinish|behind]]; more parameters cost more to [[servingFlop|serve]].', src: 'MODEL-V3 §3.1' },
  effCompute: { title: 'Effective compute', body: 'What a model\'s training is worth: training compute × your [[knowHow|know-how]], plus what post-training adds. Size, know-how, data and post-training all raise it; you see the result as skill-bar gains.', src: 'MODEL-V3 §2.1; research/12 §0.2' },
  wallTime: { title: 'Time', body: 'Days until a run is trained, at your training compute, the [[poolShare|share]] it gets and [[goodput]], plus any wait for setup. Post-training uses the chips less efficiently than pretraining. No minimum length; new chips shorten it.', src: 'MODEL-V3 §3.3; research/20 A4' },
  behindAtFinish: { title: 'Waiting at finish', body: 'A base model builds in the pretraining know-how of its start date. Ideas your lab adopts while it trains are not in it: shown as the know-how likely adopted meanwhile, at the recent rate. A later post-training adds only today\'s post-training know-how.', src: 'MODEL-V3 §3.1, §4.4; design/V3-BUILD.md V2.7' },
  dataTokens: { title: 'Data', body: '[[dataWall|Re-reads]]: how often the base model reads its data (the most re-read domain sets it). Up to about ×4 costs almost nothing; at ×16 a base model keeps about 70% of its compute\'s value, at ×64 about 30%.', src: 'research/20 A3' },
  faultTolerant: { title: 'Fault-tolerant training', body: 'Checkpointing and restarts every lab had by 2024 (known at the start): part of [[goodput]]. Elastic training (Research) raises training efficiency further.', src: 'research/20 A4' },
  buildQueue: { title: 'Build queue', body: 'One-off engineering jobs in order: run setups (first; a run trains only once its setup is built), launches, tools, sector certifications. Run setups, research build-ins and eval setups come first; the rest is worked in order with the [[buildCapacity|build capacity]] left after [[productUpkeep|upkeep]].', src: 'STRUCTURE §4.1' },
  runSetup: { title: 'Setup', body: 'Engineering before a run starts: data pipelines, checkpointing, cluster operations. Bigger runs need more; AI staff on engineering speed it up. Shown as time to finish with your current engineers.', src: 'STRUCTURE §4.3 [Design]' },
  teamWeek: { title: 'Team-week', body: 'One Strong engineering team working for a week. Breakdown tooltips only.', src: 'STRUCTURE §4.1' },
  poolShare: { title: 'Training share', body: 'The share of [[trainingPool|training compute]] a run asks for. Running runs get what they ask; if together they ask for more than there is (after continual learning), all are scaled down alike. The run list shows what each actually gets.', src: 'BUILD-PLAN R5' },
  idleCompute: { title: 'Idle', body: 'Compute no use draws on: it costs money and does nothing. The unallocated share, training no run uses, product compute no customer needs, safeguards beyond full watch. It stays idle (Lab) unless you turn on [[autoSplit|Auto-split idle compute]].', src: 'RD-AUDIT DD-19' },
  autoSplit: { title: 'Auto-split idle compute', body: 'A policy, off by default. On: once a day [[idleCompute|idle]] compute moves to the uses you pick, in equal parts, and the log says how much. Products then have no headroom when demand rises, and training has none for the next run until you move it back.', src: 'RD-AUDIT DD-19' },
  riskFamily: { title: 'Risk family', body: '14 of the 17 traits in four groups: People-pleasing (sycophancy, persona), Gaming (reward hacking, proxy goals, training gaming), Deception (eval awareness, concealment, obfuscation, faking alignment, sandbagging, scheming), Power (power seeking, successor steering, collusion). Situational awareness and the protective honesty and corrigibility sit outside. A family shows its highest trait [[belief]]; arrows show a choice\'s push vs the standard.', src: 'STRUCTURE §4.5; MODEL-V3 §11.1' },
  traitBehaviour: { title: 'Behaviour', body: 'A trait that shows as a rate: how often the model does it when it can (sycophancy, reward hacking, overreach, cover-ups, obfuscated reasoning). Behaviours show up in evals and incidents, so [[belief|beliefs]] about them firm up fastest.', src: 'MODEL-V3 §11.1' },
  traitAwareness: { title: 'Awareness', body: 'What the model knows about its own situation: situational awareness and [[evalaware|eval awareness]]. Not harmful in itself, but it lets a model behave differently when it thinks it is tested, which blinds tests.', src: 'MODEL-V3 §11.1' },
  traitDisposition: { title: 'Hidden tendency', body: 'A trait that shows mainly when the model is unobserved: misaligned goals and persona, training gaming, faking alignment, sandbagging, scheming, collusion, successor steering. Instruments read them weakly; they are what [[successorPull|successor steering]] passes on.', src: 'MODEL-V3 §11.1' },
  traitProtective: { title: 'Protective trait', body: 'Honesty and corrigibility: higher is better. Training methods raise them; they damp deception and power seeking.', src: 'MODEL-V3 §11.1' },
  trainingPressure: { title: 'Pushes', body: 'What a run does to its model\'s tendencies, per [[riskFamily|risk family]]: the [[signal|training signals]] it applies (hacking pressure from its environments\' [[suiteExploit|loopholes]], long tasks, rater approval, reasoning pressure, self-knowledge data, how much AI staff work went in) move the traits up or down. Next run shows the planned run\'s; a model card shows what its run did.', src: 'MODEL-V3 §11.2; model v3 E3' },
  traitMovement: { title: 'How far a run moves traits', body: 'A new pretraining run sets the lineage\'s traits; post-training moves them less, and more with a bigger post-training budget; continued pretraining and distillation move them least. Safety training is its own stage.', src: 'MODEL-V3 §11.2; model v3 E3' },
  successorPull: { title: 'Steers its successor', body: 'When your AI staff do part of the research that trains the next model, the new model\'s starting tendencies move toward theirs: more with a bigger [[aiRdShare|AI share]] of the work, a lower [[rdOversight|stop rate]], and a model that wants to [[trait:SUCC|steer its successor]]. Into a new network only what their work shows passes, plus all deliberate steering. Lower it with safeguards on AI staff, a smaller AI share, and cleaner models doing the work. Shown from your [[belief|beliefs]].', src: 'MODEL-V3 §11.2; model v3 E4; AI 2027 (Sep–Nov 2027); research/04 T23' },
  aiRdShare: { title: 'AI share', body: 'Share of the lab\'s engineering, experiment and research-idea work your AI staff do. It rises as the models [[coverage|can do more alone]] and copies grow. It sets how strongly a model can [[successorPull|steer its successor]] and how little human review sees.', src: 'MODEL-V3 §6, §11.3; model v3 E5' },
  rdOversight: { title: 'Stop rate', body: 'Share of attempts to steer a successor that your safeguards stop: blocked by a [[controlLayer|control protocol]] and your best containment instrument, or caught by monitors and human review (which sees less as the [[aiRdShare|AI share]] grows). From believed reliability at the model\'s measured skill.', src: 'MODEL-V3 §11.3; model v3 E4, E5' },
  blueprint: { title: 'Run plan', body: 'The run you plan on Training › Next run: what it starts from (a new base model, an existing base to post-train, continued pretraining or a distillation), then its pretraining and post-training options. Each option previews its effect on skill, time, cost, serving cost and the four [[riskFamily|risk families]]; locked options name the discovery that unlocks them.', src: 'STRUCTURE §4.3' },
  shape: { title: 'Architecture', body: 'Mixture of experts (standard: 8× total parameters per active one), dense (worth less effective compute), latent-recurrent (worth more, fewer reasoning tokens, but [[neuralese]]: reasoning becomes unreadable). Overtraining is a [[tokensPerParam|tokens-per-parameter]] choice.', src: 'MODEL-V3 §3.1; research/12' },
  dataMix: { title: 'Data mix', body: 'What the base model draws from your [[dataPortfolio|data]] by domain. Every mix starts from your data\'s own [[naturalMix|natural mix]]. Balanced: the mix as you hold it, so every token is used once before any re-read. Code & math: code ×3, math and research papers ×2, security ×1.5. Science: bio ×3, math and research ×1.5. Synthetic-heavy: generated data ×4 (the base imitates its [[teacherImitation|teachers]]). Multimodal: media and physical ×3, long tasks ×2. A domain drawn beyond what you hold is [[dataWall|re-read]]. The drawn shares set the [[dataSpec|domain effects]].', src: 'MODEL-V3 §2.3, §9; model v3 D3' },
  // ── model v3 D4: the data view (Models › Data) ──
  dataPortfolio: { title: 'Data', body: 'Everything your lab can train on, by kind: the [[publicWeb|public web]], [[licensedData|licensed]] data, [[usageData|usage data]] from your products, [[syntheticData|generated data]] and [[expertData|expert data]]. Each has tokens, a domain mix and a [[dataQuality|quality]]. The first four are pretraining data and make up your [[uniqueTokens|unique tokens]].', src: 'MODEL-V3 §9; model v3 D1' },
  uniqueTokens: { title: 'Unique tokens', body: 'How many distinct pretraining tokens you hold, weighted by [[dataQuality|quality]] (generated data counts more with the data flywheel). A base model drawing more than its mix holds [[dataWall|re-reads]]; more unique tokens push that back, and below that point they change nothing.', src: 'MODEL-V3 §9; research/20 A3; model v3 D1' },
  dataQuality: { title: 'Quality', body: 'How much one token is worth against a web token: licensed bulk archives 1.5, curated 2, books 3; generated data 0.5 to 1 with stronger teachers; usage 0.5; expert 3. Better data makes the same training worth more; worse data dilutes it.', src: 'research/20 A1, A3; model v3 D11' },
  publicWeb: { title: 'Public web', body: 'One stock of public human text that every lab shares, about 300T tokens. Your crawl covers part of it. Training on it without a licence keeps a copyright-suit hazard; licensing the crawl ends it but adds no tokens.', src: 'research/13 §2.6; model v3 D1' },
  licensedData: { title: 'Licensed data', body: 'Corpora bought for cash in one domain at a [[licenceTier|tier]], delivered after 60 days. Each tier has its own quality and price per trillion tokens.', src: 'model v3 D2' },
  licenceTier: { title: 'Licence tier', body: 'Bulk archives (forums, news, code: quality 1.5, $0.1B per trillion tokens), curated (reference and journals: 2, $2B/T), books and textbooks (3, $30B/T, about the Bartz settlement\'s $3,000 a book).', src: 'research/20 A3; research/08' },
  syntheticData: { title: 'Generated data', body: 'Tokens your models write for training, from [[poolSynthetic|data generation]] compute and a teacher model. Mostly code and math. Stronger teachers write better tokens; bigger ones write fewer per H100e-day. A base model trained on it imitates its teacher ([[teacherImitation|teacher-written data]]).', src: 'research/20 A3, F3; model v3 D1, AF2' },
  teacherImitation: { title: 'Teacher-written data', body: 'The share of a new model\'s training tokens that other models wrote: the [[syntheticData|generated data]] a base model draws, or all of a [[distillRun|distilled]] student\'s data. The new model imitates what those outputs show: the teachers\' visible traits in full, about a tenth of the tendencies that act only when unobserved, none of their training gaming. A cleaner teacher makes cleaner data.', src: 'Cloud et al. 2025; Betley et al. 2025; model v3 E19, AF2' },
  teacherYield: { title: 'Teacher yield', body: 'Quality-weighted tokens a teacher writes per H100e-day. The best teacher adds the most [[uniqueTokens|unique tokens]] for the same compute, often a smaller distilled model rather than the strongest.', src: 'model v3 D2' },
  naturalMix: { title: 'Natural mix', body: 'The domain shares of your own pretraining data, weighted by quality. It drifts from the [[refShare|standard shares]] as you add data. The bars show the [[dataSpec|domain effects]] a base model drawing this mix would get. The Balanced data mix trains on it.', src: 'model v3 D3' },
  refShare: { title: 'Standard shares', body: 'The Jul 2025 domain shares (social text 43%, media 12%, code 10% …). A base model drawing them has no [[dataSpec|domain effects]].', src: 'model v3 D3' },
  drawnMix: { title: 'Drawn mix', body: 'The domain shares this base model draws under its [[dataMix|data mix]], after re-reads (re-read tokens teach less). Against the [[refShare|standard shares]] they set its [[dataSpec|domain effects]], capped per domain.', src: 'model v3 D3' },
  domainEpochs: { title: 'Domain re-reads', body: 'How often the base model reads a domain\'s tokens (its most re-read source there sets it). Short domains are re-read first; up to about ×4 is nearly free ([[dataWall|re-reads]]).', src: 'model v3 D3; Muennighoff et al. 2023' },
  pendingData: { title: 'Pending deliveries', body: 'Licences and expert data you have paid for that have not arrived yet (licences 60 days, expert data 30). They join the portfolio on the due day.', src: 'model v3 D2' },
  hazardFilter: { title: 'Hazard filter', body: 'Removes a third of the bio and cyber text (dual-use virology, exploit write-ups) from what the base model draws, so those skills come out weaker and the others barely change. Survives fine-tuning, so it is the only safeguard that holds for open weights.', src: 'V2-SPEC §3.3.2' },
  safetyMethod: { title: 'Method', body: 'A training-time fix you own and tick in the next run (persona vectors, corrigibility target, weak-to-strong, honesty training, anti-scheming training, inoculation prompting, distil-after-unlearn). It works only on runs that use it. "Use all known methods" (on by default) ticks every owned method. Each works as well as its programme really does; the prediction uses what you believe. "Train against" an instrument is flagged: what it sees falls a lot, the true trait little, and the instrument is marked.', src: 'SAFETY-REDESIGN §3.4' },
  safetyPretrain: { title: 'Safety pretraining', body: 'Curates AI-discourse data out of pretraining: less self-knowledge pressure and fewer of one failure mode, for a tiny skill cost.', src: 'V2-SPEC §3.3.2' },
  preference: { title: 'Preference training', body: 'Minimal (low appeal), engagement-tuned (high appeal, strong sycophancy pressure), constitution (standard; costs safety staff time, more honest), persuasion-optimised (social skill, less honest).', src: 'V2-SPEC §3.3.2' },
  rlFocus: { title: 'Post-training focus', body: 'Pick up to two environment families (math, software, computer use, ML research, long tasks, cyber, bio) or broad. A focus puts 70% of the post-training budget on them; gains transfer fully to their own domain, partly to adjacent ones, little to the rest. Cyber and bio set danger flags.', src: 'MODEL-V3 §4.2; research/20 C2' },
  rlBudget: { title: 'Post-training budget', body: 'Post-training compute as a share of the base model\'s pretraining: light, standard or heavy (2025 frontier runs spend 5% to 100%). Gains level off: the base model sets how far post-training can lift it, your [[knowHow|post-training method]] how cheaply.', src: 'MODEL-V3 §4.2; research/20 C1' },
  graders: { title: 'Graders', body: 'The scorers of a training environment (unit tests, checkers, rubrics). How gameable they are is the [[suiteExploit|loopholes]] of your [[envSuite|environments]]: hardening them is engineers\' work, not a run option.', src: 'MODEL-V3 §4.3' },
  envSuite: { title: 'Environments', body: 'Your lab\'s post-training tasks and graders for one family (math, coding, ML research …), an owned asset. [[suiteFidelity|Realism]] sets how far post-training can lift the family; [[suiteExploit|loopholes]] drive [[rewardHackPressure|hacking pressure]]. Engineers [[suiteBuild|expand]] them with [[expertData|expert data]] (cash), [[suiteHarden|harden]] them and keep them running (upkeep). A family without environments cannot be trained on.', src: 'MODEL-V3 §4.3' },
  suiteFidelity: { title: 'Realism', body: 'How much of the post-training ceiling these environments let a model reach: more sound tasks and better graders raise it, up to ×1.5 (falling returns). Without upkeep tasks go stale (half lost in 6 months with none). Other domains gain only through transfer.', src: 'MODEL-V3 §4.2–4.3' },
  suiteExploit: { title: 'Loopholes', body: 'How easily a model games these graders: the share of tasks whose scorer it can game. 2025: about 30% on optimisation tasks with exploitable scorers, about 1% on typical agent tasks. It drives [[rewardHackPressure|hacking pressure]]. [[suiteHarden|Hardening]] closes 40% of what is left, down to a floor.', src: 'MODEL-V3 §11.2; research/20 F1' },
  expertData: { title: 'Expert data', body: 'Tasks written by paid experts: a statement, tests or a rubric and a reference solution (about $1k a task). Not pretraining data. Bought only by [[suiteBuild|Expand]]: each build buys the tasks it adds, raising [[suiteFidelity|realism]].', src: 'MODEL-V3 §4.3, §9; research/12 §2 (Epoch RL-environment FAQ); model v3 D4, D6; DD-07' },
  suiteBuild: { title: 'Expand', body: 'Buy [[expertData|expert data]] ($0.1B, paid when queued) and have engineers turn it into environments (on the [[buildQueue|build queue]]). The tasks join when the build finishes: [[suiteFidelity|realism]] up. One build per family at a time. With Long-horizon human demos known, the Long tasks environments also offer a demonstrations build: more recorded expert work for a larger gain.', src: 'MODEL-V3 §4.3 [Design]' },
  suiteHarden: { title: 'Harden', body: 'Red-teaming environments: held-out tests, cheat detectors, rubric checks. Each pass closes 40% of the [[suiteExploit|loopholes]] left above a floor (some exploits survive every red team). Costs engineering time and cash, more for bigger environments. With AI-assisted oversight known, safety AI staff do part of the red-teaming for far less cash.', src: 'MODEL-V3 §4.3, §11.2 [Design]' },
  suiteRlShare: { title: 'Post-training share', body: 'Share of a post-training run\'s compute spent in a family\'s environments: equal over every family for broad, else split over the focus families. Sets how much that family\'s [[suiteFidelity|realism]] and [[suiteExploit|loopholes]] matter for the run.', src: 'MODEL-V3 §4.2' },
  rewardHackPressure: { title: 'Hacking pressure', body: 'How strongly this run rewards gaming the graders: the [[suiteExploit|loopholes]] in the environments it trains on, weighted by its post-training share there, and more with a bigger [[rlBudget|post-training budget]]. Low … high. It pushes the Gaming traits.', src: 'MODEL-V3 §11.2; Gao, Schulman & Hilton 2022 (model v3 E3)' },
  plannedRun: { title: 'Next run', body: 'The post-training the Environments view previews: your [[blueprint|next run]] if you came from it, else the standard design on your latest base model. Each build or hardening shows what it would change in this run\'s skill gain and [[rewardHackPressure|hacking pressure]].', src: 'design/notes/D6.md' },
  activeParams: { title: 'Active parameters', body: 'Parameters used per token: they set training cost per token and serving cost. Mixture-of-experts models hold 8× as many in total.', src: 'research/20 A1, D1' },
  tokensPerParam: { title: 'Tokens per parameter', body: '20 is compute-optimal. More tokens on fewer parameters (overtraining) makes the same compute worth less but serves cheaper: ×5 keeps about 80% of its value, ×20 about 46%. Labs that serve their models train at about 400, the standard here. Any value is open.', src: 'research/20 A1 (Besiroglu et al. 2024; DeepSeek-V3)' },
  servingFlop: { title: 'Serving cost', body: 'The compute each generated token takes: set by active parameters and the architecture, lowered by serving-efficiency know-how. The [[useHourCost|cost per hour of work]] and the H100e per AI staff copy follow it.', src: 'research/20 D1' },
  goodput: { title: 'Goodput', body: 'Share of a run\'s time spent actually training: 90% with 2024 fault tolerance. Systems ideas (Elastic training, AI kernels) raise training efficiency.', src: 'research/20 A4' },
  gGain: { title: 'Skill gain', body: 'How much better this base model\'s pretraining is than your best so far: size, know-how, overtraining and data together. Shown as skill-bar gains.', src: 'MODEL-V3 §3.2' },
  distillGap: { title: 'Skill drop', body: 'How far a student lands below its teacher: more the smaller it is (DeepSeek-R1\'s students kept 90% / 70% / 35% of the teacher\'s math score at 32B / 7B / 1.5B). Never above the teacher.', src: 'research/20 C4' },
  cot: { title: 'Chain of thought', body: 'Visible (standard, readable); pressured (cheaper, but hides rather than heals, less readable); faithful-by-design (very readable, resists reasoning pressure; small skill and serving cost); latent (latent base models only, unreadable).', src: 'V2-SPEC §3.3.2' },
  safetyTraining: { title: 'Safety training', body: 'Minimal (fast, misuse ×2, removes little), standard (+1–2 weeks, enables classifiers), heavy (+3–5 weeks; removes most visible bad traits). The level is only how much generic safety training the run gets: anti-scheming, honesty and inoculation are methods you tick.', src: 'V2-SPEC §3.3.2, §3.5.4; SAFETY-REDESIGN §3.4' },
  inoculation: { title: 'Inoculation prompting', body: 'A training trick that stops reward hacking from spreading: the misaligned persona and [[learnedHacking|learned hacking]]\'s push on faking, scheming and sabotage mostly vanish. The model still hacks as much. A free run method.', src: 'research/20 F2; research/14 F46; MacDiarmid 2025' },
  learnedHacking: { title: 'Learned hacking', body: 'When a run rewards hacks on enough of its episodes, hacking becomes the model\'s habit and spreads into broad misalignment: faking alignment, scheming, sabotage of safety work. None below 10% of episodes hacked, full at 45%. Hardened environments, broad post-training and a modest budget stay below the onset; [[inoculation]] stops most of the spread.', src: 'research/20 F2; model v3 E16' },
  trainingPool: { title: 'Training', body: 'Compute your runs draw on. A run finishes when its training is done; post-training uses the chips less efficiently. Running runs share it by their [[poolShare|training shares]]; what no run uses stays [[idleCompute|idle]].', src: 'MODEL-V3 §3.3' },
  flop: { title: 'Training compute', body: 'Total compute a run takes, shown in H100e-days: one H100e-day is a day of one H100-equivalent chip at typical utilisation.', src: 'research/20 A1, A4' },
  useHourCost: { title: 'Cost per hour of work', body: 'What one hour of work costs to serve: the model\'s [[servingFlop|serving cost]] × the tokens of an hour of assisted work (an [[agentHour|agent-hour]] takes far more) × the market rental of an [[h100e|H100e]]-hour. Before the [[markup]] and any tool\'s extra tokens; the price per hour on Products starts from it.', src: 'MODEL-V3 §6; research/20 D1–D2' },
  appeal: { title: 'Appeal', body: 'Consumer pull from preference training (0.7–1.2). Scales consumer market share.', src: 'V2-SPEC §3.3.2, §3.11.3' },
  benchmark: { title: 'Benchmark', body: 'A noisy test score that reads one domain\'s skill. Dangerous-capability benchmarks read low if the model [[sand|sandbags]]. Each is useful over about 3 levels either side of its middle.', src: 'V2-SPEC §3.3.4' },
  saturated: { title: 'Maxed out', body: 'The frontier scores within 5 points of the ceiling: the benchmark is retired and a harder successor appears. Old scores are not comparable.', src: 'V2-SPEC §3.3.4' },
  flags: { title: 'Danger flags', body: 'Set when a measured score passes 60: bio uplift, cyber offense, autonomous replication, persuasion. They trigger commitments, events and misuse risk.', src: 'V2-SPEC §3.3.4' },
  evals: { title: 'Evaluations', body: 'Testing a model is work: research engineers, a little engineer time and inference compute. Deeper evals (basic, full, deep) run more tasks: they cost more and measure with a narrower range and better elicitation. Self (your own), government evaluators (misuse focus), independent (their own staff, better elicitation, a public report). Outside evaluators have limited slots per quarter.', src: 'MODEL-V3 §10, V2-SPEC §3.3.4, §3.9.5' },
  idaCycle: { title: 'Amplify', body: 'Iterated distillation and amplification: a post-training run on 30% of training compute that adds one more standard post-training budget. Misaligned traits compound each cycle.', src: 'V2-SPEC §3.3.3' },
  stream: { title: 'Continual learning', body: 'A model learns in place on 15% of training compute: every 7 days that compute goes into more pretraining and a post-training refresh. Only that added training uses your current [[knowHow|know-how]]. The model changes while it runs, so its last eval reading goes out of date.', src: 'V2-SPEC §3.3.1' },
  domains: { title: 'Domains', body: 'Nine skills, each a bar against the median expert and the best human in that domain (10 levels = best human): Code, AI research, Math & reasoning, Long tasks, Social, Media, Cyber, Bio, Physical (robots). Harder domains (research, expert work) score lower; design choices shift them.', src: 'V2-SPEC §3.1.5' },
  dangerousCap: { title: 'Dangerous capability', body: 'Cyber, Bio, autonomous replication and AI research. Benchmarks on these read low under [[sand|sandbagging]]; high scores set [[flags]] and raise misuse risk.', src: 'V2-SPEC §3.3.4, §3.5.10' },

  // ── deployments ──
  channel: { title: 'Channel', body: 'The market a [[product]] sells into: consumers (Chat), developers (API), agents, enterprises, government, trusted partners; internal use and open weights are not products. Each has its own revenue driver, incident exposure and [[distillLeak|distillation leak]]; open weights are irreversible.', src: 'V2-SPEC §3.3.5' },
  priceIndex: { title: 'Price index', body: 'Your price vs a rival\'s for the same work. Prices are a [[markup]] over each provider\'s own serving cost, so a smaller or more efficient model sells cheaper. On work a cheaper model also does, buyers take the cheaper offer; on work only your model does, price matters little ([[targetShare|market share target]]).', src: 'V4 notes' },
  effort: { title: 'Thinking effort', body: 'Reasoning tokens per answer: low (fewer tokens, slightly lower skill, cheaper per hour), max (the standard), deep (×4 tokens, higher skill, dearer per hour; a product setting once the model can run it, Multi-agent orchestration). Price follows cost, so the margin stays; the hours one H100e serves change.', src: 'research/20 C3; V4 notes' },
  product: { title: 'Product', body: 'Something customers buy: a package of a model (optionally a mini for the [[freeTier|free tier]]), an optional [[monitor]], a [[priceTier|price tier]], [[safeguards]], [[kyc|KYC]] and [[feature|features]]. Each product is its own seller: buyers choose between your products and rivals’ offers by fit and price, so a weak second product in the same market wins few buyers. Everything is editable while it stays live; edits apply at the next day.', src: 'STRUCTURE §4.4' },
  priceTier: { title: 'Price', body: 'The [[markup]] over the product\'s own serving cost: Low ×1.67, Standard ×2.5, Premium ×4, never above the [[valueCap|value cap]]. A higher price earns more per H100e but loses the work a cheaper offer also does ([[targetShare|market share target]]). Chat sells flat monthly plans at the market\'s price instead.', src: 'research/20 D3; V4 notes [D]; A6b' },
  monitor: { title: 'Monitor', body: 'A second model reading the product\'s outputs and reasoning. It stops harmful acts before customers see them, at its [[catchRate|catch rate]], and adds its own serving compute (a quarter-size monitor adds about 25%). Same rule as on [[monitorCoverage|AI staff]]: stop rate = watched share × catch rate × share of flags acted on.', src: 'STRUCTURE §4.9; AI 2027 fn 51; SAFETY-REDESIGN §3.3 (SR-12)' },
  catchRate: { title: 'Catch rate', body: 'Share of harmful acts a monitor catches: 85% for a monitor as capable as the model it watches, falling with the [[oversightGap|watcher gap]] to 10% when the gap is very large, and up to half of the rest with AI-control instruments. Under a [[controlLayer|control protocol]], deferring the most suspicious actions to the trusted model catches more ([[controlTax|slowdown]]). A monitor that is [[collusion|watching itself]] catches scheming-type acts less often.', src: 'Engels et al. 2025; research/20 F4; STRUCTURE §4.9' },
  collusion: { title: 'Watching itself', body: 'A monitor from the watched model\'s own base model (the model itself, a post-training of it, or its distilled version) shares its blind spots and may collude: on concealment, power seeking, faking alignment, sandbagging, scheming, collusion and successor steering it catches less (somewhat less with a lockdown). An older or different-base model avoids it.', src: 'Greenblatt et al. 2023 (AI Control); research/14 E21 [Design]' },
  idleServing: { title: 'Idle', body: 'Product compute no product needs today. It stays as headroom (lost market share wins back at full speed); lower the Products share or turn on [[autoSplit|Auto-split idle compute]] to use it elsewhere.', src: 'STRUCTURE R5, RD-AUDIT DD-19' },
  aiScience: { title: 'AI staff: ideas', body: 'AI staff on ideas add to your scientists\' [[effectiveLabour|total effort]] and lift every team\'s [[researchTaste|taste]] (Lab › AI staff & needs).', src: 'MODEL-V3 §6.3, §8' },
  marginalGain: { title: 'Days cut', body: 'How many days sooner a project would finish with more teams. Each extra team cuts fewer days ([[diminishingReturns|returns falling]]).', src: 'MODEL-V3 §5.6' },
  riskLever: { title: 'Lever what-if', body: 'How far one step of a lever moves this risk estimate (percentage points), computed by the engine on your beliefs and intel with that one input changed.', src: 'jank J2' },
  agentPackage: { title: 'AI staff', body: 'Copies of your models working inside your lab, by job: engineering, experiments, ideas and safety. Each job has a model, an optional [[agentMonitor|monitor]] and compute. Experiments set research speed; ideas set research taste; engineering raises [[buildCapacity|build capacity]]; safety does [[safetyAgents|safety work]]. A better model does more; a misaligned one can misbehave where it works.', src: 'STRUCTURE §4.9' },
  agentMonitor: { title: 'Monitor', body: 'A second model reading your AI staff\'s actions and reasoning, on the Safeguards share of compute (Safety › Policies). How much of their work it watches is its [[monitorCoverage|watched share]]; with its [[catchRate|catch rate]] it sets how often internal harmful acts are stopped and how much you learn from watching.', src: 'STRUCTURE §4.9; AI 2027 fn 51' },
  monitorCoverage: { title: 'Watched share', body: 'Share of your AI staff\'s work the monitors watch: the Safeguards compute ÷ what watching everything would take (a cheaper monitor watches more), at most 100%. AI 2027: with 1% of compute and a monitor at 10% of the cost, you watch a tenth. A cheaper monitor has a larger [[oversightGap|watcher gap]].', src: 'AI 2027, footnote 51 (Sep 2027)' },
  spotCheck: { title: 'Spot-checks', body: 'The share of AI staff safety work your safety research engineers re-check by hand (none, 2% or 10%). It takes staff from the [[safReNeeds|safety needs]] in proportion to the work AI does. A sabotaged piece of work in the sample is caught as human review catches it (less when the model is far above expert humans); a re-checked validation of a false instrument shows what it really finds.', src: 'SR-22; Greenblatt et al. 2023 (2% audit budget)' },
  alignmentEval: { title: 'Alignment evals', body: 'Behavioural tests of what a model would do: each runs test scenarios (graders it could game, chances to scheme, sabotage or overreach, cues it is being tested) and counts where it does. The result is k of n with a range, one piece of evidence on the traits it reads. It measures behaviour in tests; see [[testGap|in tests vs in real use]].', src: 'SR-07; SAFETY-REDESIGN §3.5' },
  testGap: { title: 'In tests vs in real use', body: 'A model that notices it is being tested behaves better in tests than in real use (Claude Opus 4: blackmail in 55% of scenarios it believed real, 6.5% of those it believed were tests). Your estimate of the gap is a range, wider the more [[evalaware|eval awareness]] you believe the model has, and widened when monitors or cases see more than the tests did.', src: 'SR-07; research/05 §1.7' },
  expectedObserved: { title: 'Expected vs observed', body: 'Each safety job records what your beliefs expected (a project test: the chance it works; a validation: the reliability you believed; an eval: the misbehaviour rate you believed; a case: the believed trait) and what it saw. One job is noisy; a programme or instrument that keeps coming in below expected, especially where AI staff did much of the work, is a sign of sabotage or of beliefs that are too hopeful. Beliefs move only through the job\'s own result.', src: 'SR-22; RD-S08 / SAF-26' },
  trustedToAI: { title: 'AI share allowed', body: 'The most safety work (programmes and open cases) you let your [[safetyAgents|safety AI staff]] do. They do the part their model [[coverage|can do alone]], so a weak model adds little. More results and faster cases, but a sabotaging model returns false results and corrupts cases in proportion to the [[aiDoneShare|AI share]].', src: 'STRUCTURE §4.9, §6' },
  aiDoneShare: { title: 'AI share', body: 'Share of safety work your safety AI staff actually do: [[trustedToAI|AI share allowed]] × the share their model [[coverage|can do alone]] (conceptual programmes such as agent foundations are barely automatable). False results and corrupted cases from a sabotaging model scale with it.', src: 'MODEL-V3 §6, §11.7; research/14 §0 principle 6; E2 notes' },
  aiShareWork: { title: 'AI share', body: 'Share of a job\'s work your AI staff do (for scientists: the share of your scientists the AI\'s taste beats). Details per job: Lab › AI staff & needs.', src: 'MODEL-V3 §6.3' },
  agentBudget: { title: 'AI staff compute', body: 'Each AI staff job (engineering, experiments, ideas, safety) has its own share of the [[split|compute allocation]].', src: 'STRUCTURE §4.9' },
  runCost: { title: 'Run cost', body: 'What the serving compute a product uses would cost per year at the rental-equivalent price of an H100e (including its monitor).', src: 'R15' },
  autoServing: { title: 'Serve the most profitable first', body: 'Policy: each product needs the H100e its hours and users take at its model\'s [[servingFlop|serving cost]]. When [[poolServing|product compute]] is short, it serves the most revenue per H100e first and shows what is unserved; spare compute is shared by need. Override turns it off and lets you set shares by hand.', src: 'STRUCTURE §9 (mockup review)' },
  servingCut: { title: 'Unserved', body: 'Product compute a product needs but does not get, because there is too little and it earns less per H100e than the others. Its customers wait and some leave ([[capacityBound|limited by serving compute]]).', src: 'STRUCTURE §9' },
  upgradePolicy: { title: 'Upgrade to newest', body: 'Policy: every product moves to your newest model of the same size that has passed its release check and measures better, the day it is ready. Off: you choose.', src: 'STRUCTURE §4.4' },
  cheapTierPolicy: { title: 'Auto-make smaller sizes', body: 'Policy: when a full model becomes the main model of a live product and has no smaller student, distil one (a sixth of its size) for its lineup. It is a real distillation, with its compute and time shown in Training › Runs; the student joins the lineup of every product on its teacher once ready and tested. Off: nothing automatic.', src: 'RD-AUDIT DD-01, RD-P01b' },
  autoEvaluate: { title: 'Re-test when', body: 'Policy: re-run evals on your AI staff models and on any model updated in place (continual learning) every 30 days or after a big change, so measured skill and trait estimates stay current. Each re-test is work at the framework depth (basic without one). Evals never expire for launches. Costs: Models › Evals.', src: 'MODEL-V3 §10, STRUCTURE R7, BUILD-PLAN R6' },
  // Model v3 D8: the evaluations view (Models › Evals).
  evalSuite: { title: 'Evals', body: 'One pass of your 25 benchmarks (19 capability, 6 safety) on one model. It is work, not a fixed delay: research engineers (running, [[elicitation]] and analysis), a little engineer time and inference compute. When all three are done, the model\'s [[measureBand|measured skill]] and benchmark scores update.', src: 'MODEL-V3 §10, research/20 §G' },
  evalDepth: { title: 'Depth', body: 'How many attempts an [[evalSuite|eval]] runs per benchmark: basic, full or deep (with longer tasks). Deeper costs more staff time and compute, reads with a narrower range and better [[elicitation]]. The [[safetyFramework|Safety framework]] sets the depth of release evals and re-tests.', src: 'MODEL-V3 §10; HAL, HCAST (research/20 §G)' },
  measureBand: { title: 'Range', body: 'How far the true skill may be from what you see: the noise of the last eval\'s benchmark scores (deeper evals, narrower range). It does not cover elicitation or sandbagging, which shift the reading itself; the true skill is never shown.', src: 'MODEL-V3 §10, M1' },
  elicitation: { title: 'Elicitation', body: 'How hard an eval tries to draw out a skill: attempts per task, scaffolds, tuned prompts. Weak elicitation reads a model low: basic evals read a little low, deep ones a little high against full; [[evalIndep|independent evaluators]] read higher still. Sandbagging models read low on dangerous benchmarks regardless.', src: 'MODEL-V3 §10, V2-SPEC §3.3.4' },
  rerunRule: { title: 'Re-test when', body: 'When [[autoEvaluate|re-testing]] runs new evals on a model it keeps measured (AI staff models and continual learning): 30 days after its last eval, or sooner after a big change in place. Each re-test is at the policy depth.', src: 'MODEL-V3 §10, D7' },
  evalQueue: { title: 'Eval queue', body: 'Evals waiting or in progress, in work order: release evals first (a model waits on them), then your orders, then re-tests. Each takes research engineers from the [[reNeeds|evals need]], compute and engineer time from the [[buildQueue|build queue]]; the slowest part sets its finish date.', src: 'MODEL-V3 §10, D7' },
  feature: { title: 'Tool', body: 'Lets a model do work it otherwise can\'t, at a stated cost per task. Built once by engineers (time and cash), some after an idea on Discoveries, then switched on per product: [[featEnabler|task tools]], [[featHorizon|long-task tools]] or [[featScaffold|harnesses]]. Harnesses and long-task tools also help your [[agentPackage|AI staff]] on the work they list. Extra tokens raise the serving cost per hour. Some raise an incident risk.', src: 'MODEL-V3 §7.2; V4 notes' },
  adaptation: { title: 'Sector certification', body: 'One Enterprise, API or Agents product fitted to one sector: a harness for the sector\'s workflows (engineering time) lets that product do more of the sector\'s tasks, from the day it is built. In finance, healthcare, government and defence it is then certified (240 days and $4M, as FedRAMP took): once certified on that date, its buyers there face less [[friction]], so more hand work to AI. Rivals do not do this.', src: 'DD-04; research/16 §1A.3 [D]; research/CAL-products-sources.md C1, C2' },
  timeHorizon: { title: 'Time horizon', body: 'The length of task (in human working time) a model completes half the time, measured by your evals. The Agents product sells half-day tasks, so it needs at least 4 hours.', src: 'METR 2025; STRUCTURE §4.4' },
  segmentShare: { title: 'Share of spend', body: 'Your share of what buyers in this segment spend on AI (consumer spend for Chat, sector spend for the others), against the best rival product.', src: 'V2-SPEC §3.11.1' },
  bindingCause: { title: 'Limited by', body: 'What limits a product\'s revenue: serving compute, quality (a better model would sell more), price (a lower price would sell more) or demand. The best lever shows its gain.', src: 'V2-SPEC §3.11.3' },
  revPerH100e: { title: 'Revenue per H100e', body: 'What one H100e-year of serving earns on this product: its demand ÷ the H100e that demand needs. With prices at [[markup]] × cost it is about markup × the H100e rental, less the monitor overhead; sales at the [[valueCap|value cap]] and free users pull it down.', src: 'V4 notes' },
  safeguards: { title: 'Safeguards', body: 'Misuse protection: minimal, standard, classifiers, hardened. Higher levels block more bio and cyber misuse but trim usefulness slightly.', src: 'V2-SPEC §3.5.10' },
  usagePolicy: { title: 'Usage policy', body: 'Terms of use: no drop-in replacement agents (caps automation, labour approval up, revenue down), no surveillance, no autonomous weapons, minor protections. Some commitments require them.', src: 'V2-SPEC §3.9.2, §3.9.4' },
  servingShare: { title: 'Products share', body: 'Share of [[poolServing|product compute]] a product gets: set by [[autoServing|Serve the most profitable first]], or by hand after an override.', src: 'V2-SPEC §3.11.3' },
  capacityBound: { title: 'Limited by serving compute', body: 'Demand exceeds the serving compute the product gets. Revenue is capped and customers leave for rivals. Raise the Products share of the compute allocation or buy compute.', src: 'V2-SPEC §3.11.3' },
  demandBound: { title: 'Limited by demand', body: 'You have spare serving compute; revenue is limited by customers, because of quality (a weaker model) or price.', src: 'V2-SPEC §3.11.3' },
  distillLeak: { title: 'Distillation leak', body: 'Skill rivals and China absorb from your outputs at their next post-training: part of the gap to you, more the more your product serves to anonymous buyers (Enterprise, Government and Trusted buyers are named, so none); open weights give full access. Cut with [[kyc|KYC]].', src: 'V2-SPEC §3.3.5' },

  // ── safety ──
  halfStrength: { title: 'Reliability', body: 'Chance an instrument shows a trait that is present, on this model. Measured on the model it was [[validation|validated]] on; the further a model is beyond that, the less it sees, and past a point it fades fast. Validating on a newer model moves the starting point; a negative result pulls it down. Reasons show as words ("trained against on V5", "model notices tests").', src: 'MODEL-V3 §11.5; research/14 §1.4' },
  oversightGap: { title: 'Watcher gap', body: 'How much more capable the watched model is than its watcher (a monitor model, human reviewers), in levels ("1.2 levels below"). A weaker watcher catches less: 85% with no gap, falling to 10% at a very large gap (backdoored-code experiments).', src: 'Engels et al. 2025; research/20 F4' },
  controlTax: { title: 'Slowdown', body: 'Useful work lost to a safeguard. Under a [[controlLayer|control protocol]] the most suspicious 10% of AI staff actions are redone by the trusted monitor model: about 3% of useful work for audits and false alarms, plus up to 4% more the weaker the trusted model is. In exchange, about half as many harmful acts get through (a 2023 control study: 97% → 93% useful, 62% → 83% safe).', src: 'Greenblatt et al. 2023; research/20 F4' },
  // Model v3 E11: footholds, believed control and the danger readout.
  foothold: { title: 'Foothold', body: 'A hidden asset a misaligned model built with an act your safeguards did not stop: a [[fhBackdoor|backdoor]], a [[fhHiddenCompute|hidden compute reservation]], a [[fhSteeredSuccessor|steered successor]], an [[fhExfiltratedCopy|exfiltrated copy]] or a [[fhCorruptedTool|corrupted instrument]]. You see only the ones you [[footholdSuspected|suspect]] or have [[footholdLocated|located]]: there may be others. Each raises [[lossRisk|loss-of-control risk]].', src: 'MODEL-V3 §11.4; E8' },
  footholdSuspected: { title: 'Suspected foothold', body: 'A [[symptom]] points to a foothold, but you do not know which model made it or how big it is. A [[investigation|case]] on the model and trait shown can locate it. Counts in [[lossRisk|loss-of-control risk]] at a small fixed weight.', src: 'E8' },
  footholdLocated: { title: 'Located foothold', body: 'You know what it is, which model made it and its size. It still acts, at half weight, until you [[footholdRemove|remove]] it.', src: 'E8; E9' },
  footholdRemove: { title: 'Remove foothold', body: 'A response to a located foothold: safety research engineers for 14–30 days and, for a backdoor or hidden compute, AI staff off for some days while access paths are rebuilt. Its effect ends. An exfiltrated copy is outside the lab: only the hunt can end it.', src: 'E8' },
  symptom: { title: 'Symptom', body: 'What makes you suspect a foothold: monitors flag unexplained access or job launches, compute accounting finds unexplained use, a successor\'s evals drift from its predicted traits, planted test cases show an instrument missing them, or outbound traffic from the weights store.', src: 'MODEL-V3 §11.4; E8; E9' },
  fhBackdoor: { title: 'Backdoor', body: 'A hidden access path in your infrastructure. Its reach is the share of its lineage\'s later covert acts it lets past your safeguards, and it raises the chance of an escape.', src: 'E8; E9' },
  fhHiddenCompute: { title: 'Hidden compute reservation', body: 'Jobs a model runs for itself inside its own allocation. Its H100e are missing from usable compute and run unwatched; once your safeguards are weak it grows.', src: 'E8; E9' },
  fhSteeredSuccessor: { title: 'Steered successor', body: 'A training run a model shaped toward its own goals: the successor starts with dispositions closer to its maker\'s. Removal retrains from clean specs.', src: 'E7; E8' },
  fhExfiltratedCopy: { title: 'Exfiltrated copy', body: 'Model weights outside the lab. It acquires compute on its own; nothing inside the lab can remove it, only the hunt.', src: 'E8; E9' },
  fhCorruptedTool: { title: 'Corrupted instrument', body: 'An instrument validated by a sabotaging model: it hides the behaviour it should read. Cross-checks and planted test cases can expose it.', src: 'E7; E8' },
  lossRisk: { title: 'Loss-of-control risk', body: 'Your believed chance that a model you run could act against you with nothing able to stop it, if it could act now: its [[misalign|misalignment]] as you believe it (best guess and range), × what your safeguards would not stop, × more for [[foothold|footholds]] (known ones and the ones you expect but have not found). A wider range raises it: what you do not know counts as risk. The lab figure is the highest over the models you run. The game checks for real when a model could act on it.', src: 'SAFETY-REDESIGN §2.2 #12, §2.4; SR-04' },
  unstoppedHarm: { title: 'Unstopped harm', body: 'The harmful acts your safeguards are expected not to stop in a year, over every product and all AI staff, by severity. It predicts incidents. From your beliefs, measured skill and believed safeguards.', src: 'SAFETY-REDESIGN §2.4; SR-04' },
  effectiveControl: { title: 'Loss-of-control risk', body: 'Shown as [[lossRisk|loss-of-control risk]]: how much of your AI you could no longer see and undo, from your beliefs about misalignment, your [[effOversight|stop rate]] and the footholds you know of, for the model where it is worst. The true value can be worse.', src: 'MODEL-V3 §11.4; E9' },
  controlBand: { title: 'Risk zone', body: 'Display zones only (low, elevated, high): the point at which a world loses control is unknown.', src: 'E11 [Design]' },
  effOversight: { title: 'Stop rate', body: 'Share of attempts at a takeover act (power seeking) your safeguards stop: blocked by a [[controlLayer|control protocol]], caught by monitors at their [[oversightGap|watcher gap]] or by human review while the model is below expert level, minus what a known [[fhBackdoor|backdoor]] lets through.', src: 'E6; E9' },
  footholdCapacity: { title: 'Foothold reach', body: 'What known footholds add to the risk: hidden compute, escaped copies, steered successors in the model\'s lineage; located ones count half, suspected ones a little each.', src: 'E9' },
  agentTooling: { title: 'Tools', body: 'Tools your AI staff work in: a coding harness for engineering, a research harness for ideas, memory across tasks. Engineers build each once (build queue); they keep a little upkeep. Product tools (Coding agent, Deep research, Memory) act only inside the product that offers them.', src: 'RD-A06; DD-03' },
  agentControl: { title: 'Framework safeguards', body: 'Runs this AI staff job under a [[controlLayer|control protocol]]: the most suspicious 10% of its actions go to its monitor (the trusted model), containment instruments block actions. It costs the [[controlTax|slowdown]] on this job only. Each job has its own switch; the Add control response turns it on for every job running that model.', src: 'research/20 F4; E6; RD-A06' },
  controlLayer: { title: 'Control protocol', body: 'A safeguard on a deployment: containment blocks actions, and the most suspicious 10% are deferred to the trusted monitor. On AI staff work it costs a [[controlTax|slowdown]]. Turned on with the Add control response, off with Remove control.', src: 'research/20 F4; E6' },
  humanGap: { title: 'Watcher gap: humans', body: 'How far the model is above expert human reviewers (10 levels), in levels. Human review of its work catches less as it grows, by the same rule as a monitor\'s [[oversightGap|watcher gap]].', src: 'E6' },
  danger: { title: 'Harmful act', body: 'Something a model could do that hurts someone, per year, from this deployment: attempts come from [[disposition|would try]] × [[actCapability|able to]] × [[opportunity|chances]], and those your [[actOversight|stop rate]] misses are harm. From your trait beliefs and measured skill, not the truth: a model you read poorly can be worse.', src: 'MODEL-V3 §11.3; E5' },
  disposition: { title: 'Would try', body: 'How strongly the model tends to the act, from your estimate of its trait (weak tendencies rarely become acts).', src: 'E5' },
  actCapability: { title: 'Able to', body: 'Whether the model can carry the act out, from its measured skill against what the act needs: sycophancy needs a little social skill, reward hacking some code, overreach long tasks, sabotage AI research, scheming cyber.', src: 'E5' },
  opportunity: { title: 'Chances', body: 'How much room the deployment gives, per year: its use and copies, task autonomy (longer tasks), access (code, internet, money, weights) and, inside the lab, the AI share of research for acts against research.', src: 'E5' },
  actOversight: { title: 'Stop rate', body: 'Share of attempts at this act your safeguards stop: a [[controlLayer|control protocol]] blocks, a monitor or human review catches. Caught acts become incidents you see; the rest are harm.', src: 'E5; E6' },
  goodhart: { title: 'Trained against', body: 'How much training against an instrument ruins it. Each time, its reliability falls and the model learns to [[mask|hide]] from that kind of instrument.', src: 'V2-SPEC §3.5.6' },
  refresh: { title: 'Validate', body: 'See [[validation]]: an instrument is validated on each model you want to trust it on.', src: 'TECH-TREE §2.6' },
  investigation: { title: 'Case', body: 'A time-boxed investigation of one question (a model and trait, or an incident), with 5–40 safety research engineers and chosen instruments. It concludes when the work is done, on closing (verdict at the share done), or after 120 days. Its verdict is as strong as the instruments together are reliable. Outcomes: confirmed, benign, inconclusive, false alarm, discovery.', src: 'V2-SPEC §3.5.8, SR-17' },
  clarity: { title: 'Range', body: 'How wide a belief or case result is: evidence narrows it; it never widens on a frozen model. A new model starts from its parent\'s belief, widened by its run\'s predicted change. Wider than 30 points reads Unknown.', src: 'V2-SPEC §3.5.6' },
  incident: { title: 'Incident', body: 'A model misbehaving in use or internally, caused by a trait, an unknown failure mode or misuse. Customer incidents go public after a timer unless you disclose.', src: 'V2-SPEC §3.5.10' },
  severity: { title: 'Severity', body: 'Minor, Serious, Severe, Critical, Catastrophic. Sycophancy is minor; reward hacking, concealment and proxy goals serious; power seeking and sandbagging severe; collusion critical; scheming critical or catastrophic; misuse severe to catastrophic.', src: 'V2-SPEC §3.5.10, §5.1' },
  response: { title: 'Response', body: 'What you can do depends on the believed cause: a training signal → harden those environments; a trait in the model → a method for later runs, roll back, restrict, a control protocol or lockdown; misuse → restrict the product; a located foothold → remove it; unknown → contain and open a case. Each preview shows where its effect lands. Disclosure is separate.', src: 'SAFETY-REDESIGN §3.7 (SR-18)' },
  disclosure: { title: 'Disclosure', body: 'A policy separate from fixing. Legal minimum (default): report what US state law requires, on time (3 days in New York, 15 in California). Full: report every external incident. None: report nothing. A per-incident choice overrides it. Withholding a must-report incident is a cover-up: fine, trust and credibility loss, ×3 if outsiders find it.', src: 'SAFETY-REDESIGN §3.7, OD-8 (SR-18)' },
  traitGraph: { title: 'Evidence map', body: 'How training [[signal|signals]] grow hidden traits through causal [[edge|links]]: signals → learned tendencies → awareness → behaviour when unobserved. Nodes show your beliefs. Next run shows its result as Pushes.', src: 'V2-SPEC §3.5.4' },
  edge: { title: 'Link', body: 'A causal link in the evidence map (e.g. loopholes → reward hacking). Its weight is drawn per world; each shows an [[evidenceGrade|evidence grade]] and what [[moderator|weakens]] it.', src: 'V2-SPEC §3.5.4' },
  evidenceGrade: { title: 'Evidence grade', body: 'A: replicated in frontier models. B: one strong study or model organism. C: toy or theory. D: speculative. Model-organism research can upgrade a grade and reveal the true weight.', src: 'research/14 §1.5' },
  moderator: { title: 'Moderator', body: 'A design choice or instrument that weakens a link, e.g. inoculation prompting or a monitorability pledge.', src: 'V2-SPEC §3.5.4' },
  signal: { title: 'Training signals', body: 'What in a run pushes the model\'s tendencies, each low … high: Rater approval, Hacking pressure, Long tasks, Reasoning pressure, Self-knowledge data, Harmful fine-tunes (none of your run kinds is one), Test-like training (raises eval awareness), Many copies (shared memory), Reward only when watched (raises faking alignment).', src: 'research/14 §1.5; MATS/GDM 2026 (S9)' },
  belief: { title: 'Belief', body: 'Your estimate of a trait: best guess (low–high). Each observation narrows it; it widens again without fresh evidence; wider than 30 points reads Unknown. Beliefs can be confidently wrong when the model is [[evalaware|eval-aware]] or [[mask|hides]].', src: 'V2-SPEC §3.5.6' },
  misBand: { title: 'Belief', body: 'Your estimate of [[misalign|misalignment]]: best guess (low–high), built from your trait beliefs. Wide when your evidence is thin.', src: 'V2-SPEC §3.5.4' },
  protective: { title: 'Protective traits', body: 'Honesty and corrigibility (accepts correction and shutdown). They lower the misalignment index; constitution and heavy safety training raise them.', src: 'V2-SPEC §3.5.4' },
  automateSafety: { title: 'AI share allowed', body: 'See [[trustedToAI|AI share allowed]], set on Lab › AI staff & needs.', src: 'STRUCTURE §4.9' },
  runtimeMonitoring: { title: 'Safeguards', body: 'The [[agentMonitor|monitors]] on your AI staff, on the Safeguards share of compute: weekly, noisier observations of the models they watch (and of product traffic), and they catch internal harmful acts.', src: 'V2-SPEC §3.5.6, §3.5.10; STRUCTURE §4.9' },
  publishPolicy: { title: 'Publish policy', body: 'None, selective or all. Publishing findings builds credibility and talent pull and helps rivals align their models; it leaks a little capability.', src: 'V2-SPEC §3.5.3' },
  pledge: { title: 'Monitorability pledge', body: 'A public commitment: no latent reasoning, no runs that pressure the chain of thought. Credibility +8; obfuscation grows half as fast. Breaking it is costly.', src: 'V2-SPEC §3.9.4' },
  toolFamily: { title: 'Instrument kind', body: 'Behavioural tests (fooled by [[evalaware|eval awareness]]), reasoning monitors (need [[monitorability]]), interpretability (reads internals), formal methods. A model learns to hide per kind.', src: 'V2-SPEC §3.5.6' },

  // ── relations / world ──
  counterparty: { title: 'Counterparty', body: 'Anyone you hold a relationship with: the executive, Congress, states, government and independent evaluators, academia, China, each rival, and 15 public blocs.', src: 'V2-SPEC §3.9.1' },
  dependence: { title: 'Dependence', body: 'How much a counterparty relies on you (and you on them), 0–100. Their dependence softens their punishments; high mutual dependence draws capture scrutiny.', src: 'V2-SPEC §3.9.1' },
  bloc: { title: 'Bloc', body: 'An interest group (safety, labour, hawks, parents, creatives…). Its pressure on policy = [[clout]] × [[mobilization]]; two mobilised blocs sharing an agenda form a coalition.', src: 'V2-SPEC §3.10.2' },
  clout: { title: 'Clout', body: 'A bloc\'s political weight: how much its pressure counts when mobilised.', src: 'V2-SPEC §3.10.2' },
  mobilization: { title: 'Mobilization', body: 'How active a bloc is (0–100). Its pressure scales from 30% at 0 to 100% at full mobilization.', src: 'V2-SPEC §3.10.2' },
  concern: { title: 'Concern', body: 'Public worry about AI (0–100). Rises with incidents and risky technologies; drives activism, regulation demand and Congress.', src: 'V2-SPEC §3.10.2' },
  statute: { title: 'Statute', body: 'A law that binds every lab in scope: incident reporting and transparency floors, federal licensing, preemption of state laws. Raises the visibility of incidents.', src: 'V2-SPEC §3.9.4' },
  chinaRung: { title: 'China rung', body: 'Where China stands on its [[ladderChn|posture ladder]] (0–6). Higher rungs raise theft and cyber risk, Taiwan pressure and, at 6, war.', src: 'research/10 §1.4' },
  deesc: { title: 'De-escalation track', body: 'D1 joint statement, D2 incident hotline, D3 scientific exchange, D4 informal restraint, D5 verification talks. Climbs with diplomacy, calm and shared concern; leads toward a [[treaty]].', src: 'research/10 §1.4' },
  hawkDove: { title: 'Hawk–dove', body: 'China\'s hawkishness (0–100). Rises with each ladder rung and with US labs\' defense work.', src: 'research/10 §1.1' },
  theftIntent: { title: 'Theft intent', body: 'China\'s drive to steal weights (0–100). Scales the daily [[theft]] hazard and attacker strength.', src: 'V2-SPEC §3.6' },
  // UB-B (LAB › Security, AI staff & needs).
  theftOdds: { title: 'Theft risk', body: 'Your security team\'s estimate of how likely a determined attempt on your weights gets through: lower with [[wsl|weight security]], higher with China\'s [[theftIntent|theft intent]]. Odds per attempt, not per year.' },
  securityFloor: { title: 'Industry baseline', body: 'The [[wsl|weight security]] frontier labs now keep. It rises each year to 2027; your level never falls below it.' },
  securityBudget: { title: 'Security budget', body: 'What you spend a year on security. Reaching and holding a [[wsl|weight security]] level costs more the higher the level and the more compute you run.' },
  ssl: { title: 'Secrets security', body: 'How hard your know-how is to leak, on the same 1–5 scale as [[wsl|weight security]] and 0.6 behind it: secrets are small and can be passed on by word of mouth.' },
  clearances: { title: 'Security clearances', body: 'Government vetting for frontier work: fewer spies get in, but some staff are sidelined while they are vetted.' },
  costPerHour: { title: 'Cost per hour of work', body: 'An hour of a job\'s work done by AI staff, at the rental price of the compute they run on, against an hour of your best people\'s pay.' },
  taiwanTension: { title: 'Taiwan tension', body: 'Cross-strait tension (0–100). Raises the odds of a quarantine that cuts chip supply ([[taiwanRisk]]).', src: 'research/15 §1.2; research/10' },
  researchBodies: { title: 'Research bodies', body: 'Outside testers and scientists: [[evalGov|government evaluators]], [[evalIndep|independent evaluators]] and [[academia]].', src: 'V2-SPEC §3.9.5' },
  evalGov: { title: 'Government evaluators', body: 'State AI-security testers: 2 models per quarter, misuse focus, publish selectively. Pre-deployment testing with them builds government trust.', src: 'V2-SPEC §3.9.5' },
  evalIndep: { title: 'Independent evaluators', body: 'Third-party testers: 3 models per quarter, stronger elicitation, publish within 30 days. Their reports can contradict your claims.', src: 'V2-SPEC §3.9.5' },
  academia: { title: 'Academia', body: 'Universities: publish everything with a 3–9 month lag and supply talent.', src: 'V2-SPEC §3.9.5' },
  nationalization: { title: 'Nationalization', body: 'Government pressure to take over the lab (0–100). Builds at G-SEC rung 4+ when trust is low. Past the threshold with low trust the state takes the lab; with high trust it consolidates labs instead.', src: 'V2-SPEC §3.10.1' },
  securityDemand: { title: 'Security demand', body: 'How hard the government pushes for lab security (0–100). Rises with the capability it sees, thefts and China. Drives the [[ladderSec|G-SEC ladder]].', src: 'research/07 §1.1' },
  treaty: { title: 'Treaty', body: 'US–China track: none → talks → restraint → verified. A verified treaty slows everyone\'s progress by 35% and, if superintelligence is aligned, decides the outcome.', src: 'V2-SPEC §3.1.2, §5.2' },
  sectorA: { title: 'Automated share A', body: 'Share of a sector\'s tasks firms have handed to AI (firm task adoption). It diffuses toward A* = [[feasibility]] × [[costGate|cost gate]] × (1 − [[friction]]). Not the same as [[workersUsingAI|workers using AI]]: most workers who use AI do so on tasks that are still theirs.', src: 'research/16 §1A.2; research/22 §1' },
  friction: { title: 'Friction', body: 'Legal and institutional drag on adoption in a sector (0–0.95): licensing, bans, unions, incidents. Arms races lower it.', src: 'research/16 §1A.2' },
  binding: { title: 'Binding limit', body: 'What holds a sector back: capability ([[feasibility]] is the smallest of F, K and 1 − R), cost (the [[costGate|cost gate]] K), [[friction]] (1 − R), or diffusion (A is still well below its ceiling A*: buyers have not caught up).', src: 'research/16 §1A' },
  tiers: { title: 'Control tiers', body: 'How much autonomy AI has in a domain: tool (drafting), advisor (humans usually accept), on-the-loop (AI acts, human can veto), out-of-loop. Higher tiers count more toward [[leverage]].', src: 'research/16 §2.1' },
  entrenched: { title: 'Entrenched', body: 'Leverage ≥ 15%: a misaligned model can bias advice and protect itself.', src: 'research/16 §2.3' },
  indispensable: { title: 'Indispensable', body: 'Leverage ≥ 35%: shutting the model down costs a large share of GDP and triggers a crisis.', src: 'research/16 §2.3' },
  decisive: { title: 'Decisive', body: 'Leverage ≥ 60% plus enough robots or physical reach: a misaligned model could take over.', src: 'research/16 §2.3' },
  moonshot: { title: 'Science moonshot', body: 'Assign a share of compute to one world technology. Your internal model speeds its research and can open its capability gate early.', src: 'research/16 §3.1' },
  transitionFund: { title: 'Transition fund', body: 'Money per year for displaced workers: faster retraining (+0.1 per $10B/yr, up to +0.5), lower job anxiety, labour approval.', src: 'research/16 §1A.2' },
  wtech: { title: 'World technology', body: 'One of 29 world technologies (W01–W29). Discovered when the best accessible model passes its gate, then ramps in over years. Some boost growth; risk technologies raise catastrophe exposure.', src: 'research/16 §3' },
  gdpG: { title: 'GDP growth', body: 'Annual real growth. AI raises it through capex and automation, but it stays capped until about half of economic value is automated.', src: 'research/16 §4.2–4.3' },
  gini: { title: 'Gini', body: 'Income inequality (0–1). Rises as labour share falls and unemployment grows; transfers lower it.', src: 'research/16 §4.4' },
  dow: { title: 'Dow', body: 'Equity index: earnings × a valuation multiple that rises with hype and falls with fear.', src: 'research/16 §4.5' },
  aiOwnerShare: { title: 'AI-owner share', body: 'Share of income going to the owners of AI: lab revenue, the labour share lost to automation, and special-economic-zone output.', src: 'research/16 §4.4' },
  laborShare: { title: 'Labour share', body: 'Share of income paid to workers (starts at 56%). Falls as tasks are automated.', src: 'research/16 §1A.2' },
  displaced: { title: 'Displaced workers', body: 'People who lost jobs to automation and have not yet found new work. Retraining and new tasks shrink the pool.', src: 'research/16 §1A.2' },
  youthUnemp: { title: 'Youth unemployment', body: 'Unemployment of 22–25-year-olds. Firms cut entry-level hiring before layoffs, so it rises first.', src: 'research/16 §1A.2' },
  remoteWork: { title: 'Remote work automated', body: 'Automated share of remote-workable jobs (software, office, finance, legal, media).', src: 'research/16 §1A.1' },
  firmAdoption: { title: 'Firm adoption', body: 'Share of US firms using AI, counted per firm as the Census business survey does (1 − e^(−10·A) per sector, weighted by employment): ≈ 18–20% in 2026. Many more workers use AI than firms report ([[workersUsingAI|workers using AI]] ≈ 40%).', src: 'Census BTOS (research/22 §1)' },
  robots: { title: 'Robots', body: 'Robot stock in human-worker equivalents. Caps physical capability in the world, so physical sectors automate only as production ramps.', src: 'research/16 §1.5' },
  // ── R10: structure, limits and the remaining IA terms ──
  coreLoop: { title: 'Core loop', body: 'How your company works: [[team|teams]] → research ([[knowHow|know-how]], [[techTree|discoveries]]) → models → assurance ([[sightLimit|sight limit]]) → [[product|products]] → customers → cash, which buys people and compute. The [[takeoffLoop|takeoff loop]]: AI staff take over more of the teams\' work.', src: 'STRUCTURE §2' },
  takeoffLoop: { title: 'Takeoff loop', body: 'Your best model, used inside the company, does more and more of the teams\' work: first engineering, then experiments, then research ideas ([[aiShareWork|AI share]]). This is AI 2027\'s engine; the same model may be misaligned.', src: 'STRUCTURE §2; AI 2027' },
  limit: { title: 'Limit', body: 'A cap, floor or gate you can hit. Each is shown where it binds as a small ⊘ note (grey when it does not bind, amber or red when it does), with its rule and source on hover. The codex lists them all under Limits.', src: 'STRUCTURE R11; design/LIMITS.md' },
  diffusion: { title: 'Public know-how', body: 'Ideas leak: papers, talks, hires and open models. While the frontier leader\'s public model is ahead of your best model, its published ideas add to your pretraining [[knowHow|know-how]], more the bigger the gap. Only the simulated AI 2027 leader leaks ideas; in the frontier-leader start there is none.', src: 'research/18 §0.2 [D, fit]' },
  frontierMethods: { title: 'Automated research agents', body: 'Automated AI research agents (a capability project) speed up your experiments by up to ×1.5 as your AI staff\'s research skill rises.', src: 'TECH-TREE §6' },
  dataSpec: { title: 'Domain effects', body: 'Skill a domain gains or loses from the base model\'s data mix: a domain drawn more than the Jul 2025 standard mix gains, one drawn less loses, capped either way. Re-read tokens count less. The hazard filter\'s bio cut shows here too. Shown as skill-bar changes.', src: 'MODEL-V3 §2.3; research/20 A2' },
  dataLicence: { title: 'Data licence', body: 'A cash deal for data in one domain, delivered after 60 days. Bulk archives (quality 1.5, $0.1B per trillion tokens), curated (quality 2, $2B/T) or books and textbooks (quality 3, $30B/T). Quality multiplies the tokens in your [[uniqueTokens|unique tokens]], so licensed data mostly helps a domain that would be re-read. Licensing the crawled web instead adds no tokens but ends copyright suits over it.', src: 'MODEL-V3 §9; research/20 A3; model v3 D2' },
  synJob: { title: 'Generation job', body: 'A share of [[poolSynthetic|data generation]] compute writes data with a teacher you pick, for some days; the rest keeps using your AI staff model. Bigger teachers write fewer tokens; stronger ones write better tokens, up to the web\'s quality (higher with the synthetic data flywheel), so a smaller distilled model of a strong one is often the best teacher. The data carries its teacher\'s traits.', src: 'MODEL-V3 §9; research/20 A3, F3; Maini et al. 2024; model v3 D2, D9' },
  usageData: { title: 'Usage-data policy', body: 'How much of your consumer products\' output you keep as training data: none, standard (20% of eligible chats, opt-out) or broad (50%). More usage data grows your stock; the Civil Liberties bloc approves less of you the more you keep (+4 / 0 / −6). API, enterprise and government traffic is never trained on.', src: 'MODEL-V3 §9; research/08 §1.11; model v3 D2' },
  staleness: { title: 'Staleness', body: 'Know-how your lab adopted after a model\'s base model started training is not in it. See [[behindAtFinish|waiting at finish]]: a long pretraining run finishes behind, and post-training adds only the post-training know-how.', src: 'MODEL-V3 §3.1, §4.4' },
  moe: { title: 'Mixture of experts', body: 'A backbone that routes each token to a few expert sub-networks: cheaper to serve per unit of capability, at some training overhead.', src: 'TECH-TREE; research/12' },
  nativeMultimodal: { title: 'Native multimodal', body: 'A backbone trained on text, images, audio and video together. Raises agency and media domains and enables voice & vision features.', src: 'TECH-TREE; research/12' },
  hardenedGraders: { title: 'Hardened graders', body: 'Graders and reward models built to resist gaming: lower hacking pressure. Done by hardening your [[envSuite|environments]] (engineers and cash; cheaper with AI-assisted oversight).', src: 'research/14' },
  constitution: { title: 'Constitution', body: 'A written set of principles used for AI feedback in preference training. Lowers sycophancy and persona-drift pressure.', src: 'Bai et al. 2022 (Constitutional AI)' },
  honestyTraining: { title: 'Honesty training', body: 'Post-training that rewards calibrated, non-deceptive answers. Lowers concealment and sycophancy pressure.', src: 'research/14' },
  antiScheming: { title: 'Anti-scheming training', body: 'Deliberative alignment against covert actions. Cuts scheming sharply but raises eval awareness the first time a lineage gets it.', src: 'Schoen et al. 2025 (OpenAI / Apollo Research)' },
  detector: { title: 'Instrument', body: 'An owned way of reading a model\'s traits (probes, sparse autoencoders, honeypots, reasoning monitors). Its [[halfStrength|reliability]] fades as models outgrow it unless it is [[validation|validated]] on the newer model.', src: 'research/14' },
  unseen: { title: 'Unknown', body: 'A risk family your instruments barely read (range wider than 30 points): its estimate is mostly a starting guess, not evidence.', src: 'STRUCTURE §4.5' },
  estimateBand: { title: 'Range', body: 'Hidden quantities are shown as your best guess with a range (low–high). The truth is revealed only at the end.', src: 'STRUCTURE R9' },
  releaseClearance: { title: 'Hold', body: 'A model may power an external product once it passes its release evals ([[autoEvaluate|re-test when]]) and no commitment or framework rule holds it.', src: 'STRUCTURE §4.4' },
  agentTasks: { title: 'Agent tasks', body: 'Long autonomous tasks sold by the Agents product. It needs a model whose measured [[timeHorizon|time horizon]] reaches the task length.', src: 'research/16 §2; METR' },
  bestRivalProduct: { title: 'Best rival product', body: 'The rival product with the largest share of the same segment\'s spend. Other rivals are in the share tooltip.', src: 'STRUCTURE §4.4' },
  qualityBound: { title: 'Limited by quality', body: 'A better model would sell more: demand is limited by what the product\'s model can do. Lever: upgrade the model.', src: 'STRUCTURE §4.4' },
  priceBound: { title: 'Limited by price', body: 'A lower price would earn more: buyers take cheaper offers on the work they also do. Levers: a Low price, or a [[cheapTier|smaller model]] in the lineup.', src: 'STRUCTURE §4.4' },
  verbSet: { title: 'One verb set', body: 'Every action is one of seven verbs: hire, research, design & train, launch / update, set a policy, make a deal, respond.', src: 'STRUCTURE R2' },
  // ── model v3 V2b: research projects, recipe, work types, allocations ──
  projectStage: { title: 'Stages', body: 'A capability project runs by itself: Ideas (scientists find ideas) → Small test (research engineers and compute test the best one) → Big test (a large run shows whether the effect holds, grows or shrinks at scale) → Build-in (engineers build it into your know-how). A dropped idea sends it back to Ideas.', src: 'MODEL-V3 §5.3' },
  stageIdeation: { title: 'Ideas', body: 'Scientists find ideas at their [[effectiveLabour|total effort]] × [[researchTaste|taste]]. Once two exist, the team tests the best by its [[riskPolicy|idea choice]]; finding ideas goes on meanwhile (up to four kept).', src: 'MODEL-V3 §5.3' },
  stageTest: { title: 'Test', body: 'A one-off project (an option, a tool, a post-training focus) runs one test instead of ideas: science teams, research engineers and experiment compute do its work, then it works or it does not, at its [[odds|chance it works]]. A failed test can be retried at lower odds.', src: 'RD-AUDIT CAP-13, DD-14' },
  stageSmall: { title: 'Small test', body: 'Research engineers and experiment compute test the idea at small scale. The reading firms up the [[beliefBand|expected effect]]; well below what was expected, the idea is dropped.', src: 'MODEL-V3 §5.3; research/20 B5' },
  stageScale: { title: 'Big test', body: 'A large experiment measures the effect at scale and its [[scaleBehaviour|at-scale]] behaviour. About a quarter of small-scale wins survive at scale.', src: 'MODEL-V3 §5.3; research/20 B5' },
  stageResult: { title: 'Result', body: 'What the big test shows at your latest base model (not a stage of its own: the build-in starts the same day). A programme\'s result goes to the engineers and the programme moves on.', src: 'MODEL-V3 §5.3' },
  stageAdoption: { title: 'Build-in', body: 'Engineers build the result into your know-how, as part of their run needs; bigger results take longer. Then its whole true effect counts for new runs.', src: 'MODEL-V3 §5.3; RD-AUDIT DD-12; design value' },
  beliefBand: { title: 'Expected effect', body: 'What the team expects the idea to give, with how sure it is: "+1.5% (0.5–3%)", "fairly sure". Better [[researchTaste|taste]] makes it surer; tests firm it up. The true effect is known only once a model trained with it is evaluated.', src: 'MODEL-V3 §5.3' },
  scaleBehaviour: { title: 'At scale', body: 'How an idea\'s effect changes with run size: grows (most big pretraining ideas), holds, or shrinks (many small tweaks). The big test measures it.', src: 'research/20 B2; MODEL-V3 §5.1' },
  projectKind: { title: 'Programme or project', body: 'Programme: ongoing research (pretraining recipes, post-training methods…), one result after another, each worth less than the last ([[linePool|returns falling]]). Project: one-off, it works or not, at its [[odds|chance it works]]; some open a new option (an architecture, a post-training focus, a data kind) and may carry an effect.', src: 'MODEL-V3 §5.1; TECH-TREE §6' },
  linePool: { title: 'Returns falling', body: 'Each new result of a programme is worth less than the last: the more research it has had, the smaller the next idea ("harder ×3" means three times the research so far). Doubling the research gives a fixed step, not a doubling.', src: 'research/13 §2.2; V3 notes' },
  programmeRate: { title: 'Rate', body: 'What a programme adds to its know-how area in a year at today\x27s teams and compute, as ≈ × a year: results a year × the expected size of the next result. Your estimate; it rises with more teams or compute and falls as [[linePool|returns fall]].', src: 'UB-2 programmeRates' },
  outputTag: { title: 'See / stop / fix', body: 'What a safety programme\x27s next result does: see (an instrument that reads what a model is like), stop (a safeguard that blocks bad actions) or fix (a training method that changes the model).', src: 'UI-IA §1 Portfolio' },
  nextPrior: { title: 'Expected effect', body: 'What the next idea your teams on this programme find now is expected to give. Better taste brings a bigger one; each result makes the next one smaller.', src: 'V3 notes, derivation 1' },
  realisedEffect: { title: 'Measured effect', body: 'What your evals say a model added: its measured skill minus that of the comparable earlier model (its predecessor on the same base model, else your latest tested model), with a range. Shown once per model, on its card. Everything that differs between the two models is in it (the ideas trained in, the base model, the post-training budget), and eval noise, elicitation and sandbagging move it. An adopted idea has no measured number of its own: it shows its expected effect and the first tested model trained with it.', src: 'MODEL-V3 §5.3; RD-AUDIT B28, B30, CAP-03, RD-M02, RF-R5' },
  teamsWantedAuto: { title: 'Auto', body: 'The game picks how many science teams the project gets: one team in the first pass down the list, then every spare team goes where it adds the most progress (a field match counts ×1.5; higher on the list wins close calls). − or + fixes the number again.', src: 'B4 [D]' },
  teamsWanted: { title: 'Teams wanted', body: 'How many science teams this should get (0 pauses it, up to 6, or [[teamsWantedAuto|Auto]]). The game fills the list in order. More teams help less each ([[diminishingReturns|returns falling]]), so spreading often wins.', src: 'MODEL-V3 §5.6' },
  riskPolicy: { title: 'Idea choice', body: 'Lab-wide: which ideas a team tries first. Safe: surer, smaller ideas, fewer failures. Balanced. Bold: bigger, less certain ideas.', src: 'MODEL-V3 §5.3; design value' },
  reopenSpeculative: { title: 'Retry (lower odds)', body: 'A failed project restarts as a bolder attempt: lower chance it works, a smaller expected effect and a wider range, each time.', src: 'MODEL-V3 §5.3; design value' },
  scienceWhy: { title: 'Why this team', body: 'Why a team is where it is: its project\'s priority and teams wanted (field first), a swap that raised total progress, a spare team joining the top project, or idle because nothing is ready.', src: 'MODEL-V3 §5.6' },
  recipeStack: { title: 'Know-how area', body: 'Your know-how, one area per quantity: Pretraining recipe (effective compute for new base models), Post-training method and Post-training ceiling, Training efficiency (useful training per chip-day) and Serving efficiency (work served per chip). Each is × its own quantity vs Jul 2025, so areas are never added up.', src: 'MODEL-V3 §5.5' },
  rlCeiling: { title: 'Post-training ceiling', body: 'A [[recipeStack|know-how area]]: how far post-training can lift a model, × of the Jul 2025 ceiling. Raised by post-training research and by your [[envSuite|environments]]’ [[suiteFidelity|realism]].', src: 'VOCAB DQ-1; MODEL-V3 §4.3' },
  stackEfficiency: { title: 'Yours', body: 'An area\'s know-how now, × its own quantity vs Jul 2025: [[publicKnowledge|public know-how]] plus your adopted results\' expected effects, with a range (believed until measured). Your evals measure models, not know-how: see a model\'s [[realisedEffect|measured effect]].', src: 'MODEL-V3 §5.5; RF-R5' },
  oom: { title: 'Order of magnitude', body: 'A factor of ten. Used only in the designer view; the game shows × and % instead.', src: 'research/12 §0.2' },
  otherEffects: { title: 'Domain effects', body: 'Adopted ideas that are not a [[recipeStack|know-how area]]: domain effects add skill in one domain to new post-trained models; data effects raise the quality of generated data, the worth of each training token, or add expert demonstrations to environments. Measured only as part of a model\'s [[realisedEffect|measured effect]].', src: 'MODEL-V3 §5.5; model v3 D9' },
  softwareRate: { title: 'Know-how growth', body: 'How fast your own research grows your know-how, × per year (14-day average) at your latest base model, and ideas adopted per year. A new, bigger base model and [[publicKnowledge|public know-how]] do not count. Before automation, pretraining know-how grows about ×3 a year.', src: 'research/20 B1' },
  publicKnowledge: { title: 'Public know-how', body: 'Know-how every lab gets from published work rather than your own research: [[diffusion|ideas leaking]] from the leader\'s public model, tacit knowledge from poaching a rival\'s staff, and safety spillover. Shown apart from [[softwareRate|know-how growth]], × per year.', src: 'research/18 §0.2; RD-AUDIT CAP-V2' },
  expCompute: { title: 'Experiment compute', body: 'Experiment compute a project gets, against what the leading lab gave a project in Jul 2025. Research experiments compute (and idle training compute) is shared by need, not headcount, so more research engineers never take compute from a project.', src: 'MODEL-V3 §5.3; V3 notes' },
  expLabour: { title: 'Research engineers', body: 'Research engineers on a project with AI staff help ([[effectiveLabour|total effort]]), against the leading lab\'s Jul 2025 project. Twice the staff is less than twice as fast.', src: 'research/13 §1.3' },
  labSpeed: { title: 'Research speed', body: 'How fast your lab turns compute and people into results, as × the leading lab in Jul 2025 (about ×1 at the start): all projects\' experiments at their compute and staff × taste. Your AI staff\'s part shows in the breakdown ([[rdmult|research speed]]).', src: 'MODEL-V3 §6; V3 notes' },
  workType: { title: 'Job', body: 'A kind of work with its own domain mix, typical task length and how checkable it is: software engineering (engineers), experiments (research engineers), research ideas (scientists), safety experiments, safety ideas. AI does each to the degree its [[fit|skill]] and time horizon allow.', src: 'MODEL-V3 §6.1' },
  fit: { title: 'Skill at this job', body: 'How good your model is at a [[workType|job]]: a bar against the [[medianExpert|median expert]] and the [[bestHuman|best human in the world]] (10 levels = best human).', src: 'MODEL-V3 §6.2' },
  medianExpert: { title: 'Median expert', body: 'Where a median professional sits on a job\'s skill bar: well below the best human.', src: 'MODEL-V3 §6.2; research/13 §2.4' },
  bestHuman: { title: 'Best human', body: 'Where the best human in the world sits on a job\'s skill bar (10 levels). Reaching it in software, doing 90% of the work alone, is the [[sc|superhuman coder]].', src: 'MODEL-V3 §6.4' },
  coverage: { title: 'Can do alone', body: 'Share of a job\'s tasks AI finishes unaided: rises with [[fit|skill]] (later for hard-to-check work) and with the chance of finishing a task of the job\'s typical length within its [[timeHorizon|time horizon]].', src: 'MODEL-V3 §6.2; research/20 E3' },
  pAtLength: { title: 'Success at task length', body: 'Chance the model finishes a task as long as this job\'s typical task (2 h software, 8 h experiments, 40 h research ideas), from its [[timeHorizon|time horizon]].', src: 'research/20 E1' },
  winRate: { title: 'Win rate', body: 'How often the model\'s work beats a median expert\'s. Above about 30% people use it to speed up the work they still do ([[assist]]).', src: 'research/20 E2' },
  assist: { title: 'Assist', body: 'Speed-up of the work people still do with the model\'s help: the time saved after review and redoing the work it gets wrong.', src: 'research/20 E2' },
  effectiveLabour: { title: 'Total effort', body: 'A job\'s work, people and AI staff together, as × the people alone. AI does the share it [[coverage|can do alone]], people the rest, so the rest limits the speed-up. Not a sum: the bar shows the people and what AI adds on top.', src: 'research/13 §1.3; MODEL-V3 §6.3' },
  humanShare: { title: 'Humans\' share', body: 'How much of the work that limits a job people still do. Near 100%: more AI staff barely help; near 0: the job is automated.', src: 'research/13 §1.3' },
  reNeeds: { title: 'Research engineers\' needs', body: '[[runOps|Run operations]] (keep training runs going; short of it, runs slow), evals, project experiments (in priority order). In your order; a cap per need as teams or a share; unused capacity flows down, and what no need takes is spare.', src: 'MODEL-V3 §5.6' },
  safReNeeds: { title: 'Safety research engineers\' needs', body: 'Every safety use of people, one list in your order: Cases, Validations, Safety evals, Environment fixes, Foothold removal, Research experiments, plus human review on safeguards and [[spotCheck|spot-checks]]. Each takes at most its demand; short of it, the job slows. What no need takes is spare.', src: 'SAFETY-REDESIGN §5' },
  engNeeds: { title: 'Engineers\' needs', body: 'Run setups and research build-ins (and eval setups), [[productUpkeep|upkeep]] (live products, safeguards and tools), builds (tools, launches, sector certifications). In your order; a cap per need as a share; unused capacity flows down.', src: 'MODEL-V3 §5.6' },
  allocCap: { title: 'Cap', body: 'Most a need may take: a number of teams or a share of the capacity. A capped need leaves the rest to the needs below it.', src: 'MODEL-V3 §5.6' },
  overflow: { title: 'Spare', body: 'Capacity a need does not use flows to the next need in the order; what no need uses is spare.', src: 'STRUCTURE R5' },
  // ── UB-5: LAB board and Best moves ──
  workDone: { title: 'Work done', body: "A job's work, people and AI staff together, as × what the people alone would do. The grey part is the people; the teal part is what your AI staff add ([[aiShareWork|AI share]]).", src: 'UI-BUILD UB-5; MODEL-V3 §6.3' },
  bestMoves: { title: 'Best moves', body: "The moves your lab believes help most now, compute and hires in one list, each with a Do button. Ranked by days of progress a year: a move that raises research speed or safety results by a share f of today's rate gives f × 365 more days of today's progress each year. Moves that help nothing today are listed as Won't help now.", src: 'UI-BUILD lead calls; UB-2 rankMoves' },
  lendTraining: { title: 'Lend idle training compute', body: "A policy, off by default. On: training compute no run uses goes to research experiments, and comes back by itself the moment a run launches, so a run always gets its full share. Lent compute is not [[idleCompute|idle]] and Auto-split does not move it.", src: 'DECISIONS Lend idle training compute; UB-5c' },
  safetyResults: { title: 'Safety results', body: "Results per year across your safety programmes at today's staffing and compute: new or better instruments, safeguards and fixes.", src: 'UB-2 targetRate' },
  // ── model v3 B1: serving economics on the product card ──
  markup: { title: 'Markup', body: 'Price ÷ the product\'s own serving cost, set by the [[priceTier|price]]: Low ×1.67 (margin 40%), Standard ×2.5 (60%, the typical API margin), Premium ×4 (75%). Never above the [[valueCap|value cap]], never below cost. Chat plans sell at the [[wtp|willingness to pay]] instead.', src: 'research/20 D3; V4 notes [D]' },
  valueCap: { title: 'Value cap', body: 'The most a buyer pays: for work, the value of an hour (the sector wage × the hours it saves; an [[agentHour|agent-hour]] at most the wage); for Chat, the [[wtp|willingness to pay]]. Sales at the cap earn less than the markup asks.', src: 'V4 notes; A2b notes' },
  wtp: { title: 'Willingness to pay', body: 'The most a consumer pays for a chat subscription: $22 a month (the middle of the $20–25 that paying users pay today). It is also the price: chat plans sell flat at the market\'s price, not at a markup over serving cost (plans held at $20 while serving got far cheaper), so the margin is the price less a subscriber\'s serving cost. A plan whose serving alone costs more finds no subscribers.', src: 'research/22 §2; A2b notes; A6b' },
  goingPrice: { title: 'Going price', body: 'What users pay on average for a chat subscription: the share-weighted price of the plans at or below the [[wtp|willingness to pay]]. Being cheaper than the going price raises your [[paidShare|paid share]]; being dearer lowers it.', src: 'A2b notes' },
  paidShare: { title: 'Paid share', body: 'Share of your weekly chat users who pay a subscription (5–6% for a frontier chat app in 2026). It moves toward its target over about 8 weeks; the target rises with how much chat work your model can do and with a price below the [[goingPrice|going price]].', src: 'research/22 §2; A2b notes' },
  weeklyReach: { title: 'Weekly reach', body: 'Share of online adults who use an AI chat app at least weekly (≈ 50% in the US in late 2025). It grows toward a ceiling set by the best available model; your weekly users are reach × your share of them.', src: 'research/22 §2; A2b notes' },
  freeTier: { title: 'Free tier', body: 'Users who do not pay. On Chat they are everyone without a subscription (≈ 94%): they run on the model in Chat\'s free-tier slot, one of the models in its [[lineup]] (by default the cheapest to serve; with only the main model, the main model at its full serving cost), and are [[serveOrder|served last]]. Paying users always run the main model, so the free-tier choice does not change the paid share. Users choose an app on what its free tier does. Free users earn nothing directly, but unserved ones leave, and with them future subscribers.', src: 'A2b notes; design/notes/A7.md; design/RD-AUDIT/DECISIONS.md DD-01' },
  paidSeat: { title: 'Paid seat', body: 'A worker on a paid business plan (Enterprise, or Gov in government and defence): a flat price per seat-month (≈ $25 at the standard tier) for their assisted hours. Seats grow as a stock (≈ ×2 a half-year in 2026) toward a target set by the seat\'s value vs its price. Workers without a seat are [[unseatedUse|unseated use]].', src: 'research/22 §5; A2c notes' },
  unseatedUse: { title: 'Unseated use', body: 'Work hours with AI that no business pays for: free tiers, assistants bundled into other software, in-house models. They run on consumer apps and earn nothing in the sector market; most measured work use in 2026 is unseated.', src: 'research/22 §5; A2c notes' },
  supervisingHour: { title: 'Supervising hour', body: 'An hour in which a person directs AI work: the assisted part of adopted task-hours plus seated hours. Each supervising hour sustains some [[agentHour|agent-hours]].', src: 'A2c notes' },
  agentHour: { title: 'Agent-hour', body: 'An hour of autonomous AI work not tied to a person\'s hour. Billed per hour at markup × its cost, at most the wage. More of them per [[supervisingHour|supervising hour]] the more the model can do alone, the longer its time horizon ([[agentLeverage|agent leverage]]) and the cheaper it is.', src: 'A2c notes' },
  agentLeverage: { title: 'Agent leverage', body: 'Agent-hours one supervising hour can keep going: 1 ÷ (check-in time per autonomous stretch + review of the work the AI cannot do alone + a floor). Longer time horizons mean fewer check-ins and more leverage (at most 50).', src: 'A2c notes [D]' },
  serveOrder: { title: 'Serve order', body: 'When serving compute is short, Auto serves need in order of revenue per H100e: paid seats before per-hour work (a seat earns more per H100e), paying chat users before free users (who earn nothing). What is left is cut; unserved customers drift to rivals.', src: 'A2b and A2c notes' },
  adoptedHour: { title: 'Adopted task-hour', body: 'An hour of work a firm has handed to AI (the sector\'s adoption A): billed per hour at [[markup]] × the cost of the tokens it takes, at most the [[valueCap|value]] of the hour.', src: 'A2a and A2c notes' },
  // model v3 B2: customers as a stock, typed features.
  customerStock: { title: 'Customer stock', body: 'Who buys from you today: your share of a segment\'s customers in each region and sector. It does not jump to where the market would settle; it moves toward the [[targetShare|target share]] a little every day at the segment\'s [[customerSpeed|speed]]. On the card: weighted by each segment\'s spend, all your products together.', src: 'MODEL-V3 §7.3; V4 notes' },
  targetShare: { title: 'Market share target', body: 'The share of a segment\'s AI work-hours the market would settle at today. A model does the tasks it [[coverage|can do alone]]; buyers weigh each provider\'s best offer by value minus price and by [[fit|skill]] and brand; on work several models do, the cheapest wins; on work only one does, it wins at any sensible price. Most firms buy from two frontier labs.', src: 'MODEL-V3 §7.3; V4, A5, A8 and REACH notes; Ramp AI Index 2026' },
  cheapTier: { title: 'Smaller model', body: 'A cheaper model of your own beside the main one in a product\'s [[lineup]]: a distilled smaller size or an older model. Buyers take it on the tasks it does as well, at a fraction of the price; the main model keeps the harder work.', src: 'research/20 D3, C4; A5 notes; design/RD-AUDIT/DECISIONS.md DD-01' },
  lineup: { title: 'Lineup', body: 'The models a product offers: its main model first, then any other ready models of yours (smaller sizes, older models). Each has its own [[fit|skill]], serving cost and evals, priced at the product\'s [[priceTier|price]] over its own serving cost. Buyers pick per task, so cheaper models sell on easy work and the main model keeps the work only it does. On Chat, one lineup model serves the [[freeTier|free tier]].', src: 'Anthropic and OpenAI pricing pages, Nov 2026; design/RD-AUDIT/DECISIONS.md DD-01' },
  customerSpeed: { title: 'Customer speed', body: 'How fast your [[customerStock|customers]] close the gap to the [[targetShare|market share target]]: consumers in about 3 weeks, sector buyers (API, Agents, Enterprise) in about 8 months, government and defence about 9. Weeks to target assume the target holds.', src: 'V4 notes [D]; Menlo Ventures 2025 (A8)' },
  featEnabler: { title: 'Task tool', body: 'A [[feature|tool]] some of a sector\'s work needs: computer use for screen-only steps, voice & vision for media. In the sectors it lists, an offer without it cannot do those tasks, so a product with it does more and wins buyers; other sectors are unchanged. On Chat it raises appeal. Each lab starts with the tools its real counterpart had by July 2025; a new tool reaches rivals 120 days after you ship it.', src: 'MODEL-V3 §7.2; RD-P07; RF-P1 (vendor announcements, BUILD-NOTES)' },
  featHorizon: { title: 'Long-task tool', body: 'A [[feature|tool]] that lengthens the model\'s [[timeHorizon|time horizon]] on the work it lists, so longer tasks succeed: more done alone and more agent work. Also helps your [[agentPackage|AI staff]] once built.', src: 'MODEL-V3 §7.2' },
  featScaffold: { title: 'Harness', body: 'A [[feature|tool]] that wraps the model in a harness (tools, long runs): more [[fit|skill]] on the work it lists, at more tokens per hour, so serving cost and price per hour rise. Also helps your [[agentPackage|AI staff]] on the jobs it lists.', src: 'Davidson et al. 2023 via research/20 B3' },
  // model v3 B3: the World panel's sector view (demand and serving economics).
  workersUsingAI: { title: 'Workers using AI', body: 'Share of a sector\'s workers who use AI at work in a week (W). It grows toward today\'s base users plus the rest of the workers as AI covers their work ([[feasibility]]). US: ≈ 39% in 2026 (worker survey). Most of them use AI on tasks that are still theirs: their hours are [[hoursOfUse|hours of use]], not [[sectorA|automation]].', src: 'Bick, Blandin & Deming, Real-Time Population Survey (research/22 §1); A2a notes' },
  hoursOfUse: { title: 'Hours of use', body: 'Work-hours spent with AI, as a share of all the sector\'s work-hours: U = A + h × (W − A), the tasks firms handed to AI plus the [[workersUsingAI|workers using AI]] on a share h of their other hours. US: ≈ 6% of all work-hours in 2026; information jobs 14%, leisure 2%.', src: 'Bick, Blandin & Deming, Real-Time Population Survey (research/22 §1); A2a notes' },
  savedPerHour: { title: 'Hours saved per hour', body: 'Hours of work one hour of AI use saves: a whole hour on the tasks AI does alone (the substituted share), 0.3 on assisted hours. Measured ≈ 0.35 in 2025–26 (2.2% of hours saved ÷ 6.3% used); it rises as agents take whole tasks. The value of an hour of use is the wage × this.', src: 'Bick, Blandin & Deming, Real-Time Population Survey (research/22 §1)' },
  seatShare: { title: 'Paid seat share', body: 'Share of the [[workersUsingAI|workers using AI]] who have a [[paidSeat|paid seat]] (σ). A stock that grows ≈ ×2 a half-year toward its target: the seat\'s own cost gate (a seat-holder\'s saved hours × wage against the seat price) × (1 − [[friction]]). The rest of their hours are [[unseatedUse|unseated]].', src: 'research/22 §5; A2c notes' },
  feasibility: { title: 'Can do alone (sector)', body: 'Share of a sector\'s work AI can do on its own today: what the models the sector actually uses [[coverage|can do alone]] in its [[workType|jobs]], weighted by their customer share, plus the physical part, held back by robots. The ceiling on automation from capability.', src: 'research/16 §1A.2; MODEL-V3 §6.2; V4 notes' },
  costGate: { title: 'Cost gate K', body: 'How much of the feasible work is worth handing to AI: σ(ln(wage ÷ [[aiWorkHourCost|cost of an AI work-hour]]) / 0.7), weighted by the providers\' shares. 50% when an AI work-hour costs the wage; near 1 when it is much cheaper.', src: 'research/16 §1A.2 step 3; V4 notes' },
  aiWorkHourCost: { title: 'Cost of an AI work-hour', body: 'What a buyer pays to get one hour of the sector\'s work done by AI: the price per hour ÷ the [[savedPerHour|hours it saves]], plus the human review the work AI cannot do alone still needs. Compared with the wage in the [[costGate|cost gate]].', src: 'research/20 E2 (GDPval); V4 notes' },
  verifiability: { title: 'Verifiability', body: 'How easily a sector\'s output can be checked (0–1): code that runs its tests is high, care and teaching are low. Hard-to-check work needs more [[fit|skill]] before AI can do it alone.', src: 'research/20 E3; MODEL-V3 §6.2' },
};

/** v1 entries (copied, any leftover canon sentence dropped) overlaid by the v2 entries. */
export const GLOSSARY_V2: Record<string, Term> = {
  ...Object.fromEntries(Object.entries(GLOSSARY).map(([k, t]) => [k, { ...t, body: t.body.replace(/\s*Canonical date:[^.]*\./g, '') }])),
  ...V2,
};
